const e="hsk",t=5,n=[{num:1,title:"爱的细节",points:[{id:"5.1.1",name:"“如何”表示方式/办法",pinyin:"rúhé",type:"疑问/书面表达",explainEn:"Use 如何 to ask or talk about “how”. It is more formal than 怎么.",structure:"如何 + V / 如何 + 处理…",examples:[{zh:"我们应该如何解决这个问题？",en:"How should we solve this problem?"},{zh:"我不知道如何回答。",en:"I do not know how to answer."},{zh:"你打算如何安排时间？",en:"How do you plan to arrange your time?"}],exercises:[{q:"填空：我们应该___解决这个问题？",a:"如何",instr:"填空",instrEn:"Fill in the blank",body:"我们应该___解决这个问题？"},{q:"翻译：I don't know how to answer.",a:"我不知道如何回答。",instr:"翻译",instrEn:"Translate",body:"I don't know how to answer."},{q:"把“你打算怎么安排时间？”改得更正式。",a:"你打算如何安排时间？"}],note:"“如何”较书面，“怎么”更口语。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"如何 is more formal; 怎么 is more colloquial.",typeEn:"Question / Formal"},{id:"5.1.2",name:"介词/动词“靠”表示依靠或凭借",pinyin:"kào",type:"介词/动词",explainEn:"Use 靠 to mean “rely on / by means of”.",structure:"靠 + 人/方法 + V",examples:[{zh:"学语言要靠多练习。",en:"Learning a language depends on practice."},{zh:"他靠自己解决了问题。",en:"He solved the problem by himself."},{zh:"我们不能只靠运气。",en:"We cannot rely only on luck."}],exercises:[{q:"填空：学汉语要___多练习。",a:"靠",instr:"填空",instrEn:"Fill in the blank",body:"学汉语要___多练习。"},{q:"翻译：We cannot rely only on luck.",a:"我们不能只靠运气。",instr:"翻译",instrEn:"Translate",body:"We cannot rely only on luck."},{q:"排序：自己 / 他 / 靠 / 完成了 / 工作",a:"他靠自己完成了工作。",instr:"排序",instrEn:"Reorder the words",body:"自己 / 他 / 靠 / 完成了 / 工作"}],note:"常见：靠自己、靠努力、靠经验。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Common: 靠自己, 靠努力, 靠经验.",typeEn:"Preposition / Verb"},{id:"5.1.3",name:"副词“居然”表示出乎意料",pinyin:"jūrán",type:"副词",explainEn:"Use 居然 for something surprising or unexpected.",structure:"主语 + 居然 + 谓语",examples:[{zh:"他居然忘了我的生日。",en:"He unexpectedly forgot my birthday."},{zh:"这么难的题，她居然做对了。",en:"She surprisingly got such a hard question right."},{zh:"下这么大雨，他居然没带伞。",en:"It was raining heavily, but he surprisingly had no umbrella."}],exercises:[{q:"填空：他___没来。",a:"居然",instr:"填空",instrEn:"Fill in the blank",body:"他___没来。"},{q:"翻译：She surprisingly got it right.",a:"她居然做对了。",instr:"翻译",instrEn:"Translate",body:"She surprisingly got it right."},{q:"选择：表示非常意外用（居然 / 逐渐）。",a:"居然",instr:"选择",instrEn:"Choose",body:"表示非常意外用（居然 / 逐渐）。"}],note:"和“竟然”意思接近，常带惊讶语气。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Close to 竟然; carries surprise.",typeEn:"Adverb"}]},{num:2,title:"留串钥匙给父母",points:[{id:"5.2.1",name:"“以来”表示从过去某时到现在",pinyin:"yǐlái",type:"时间表达",explainEn:"Use 以来 after a time/event to mean “since…”.",structure:"时间/事件 + 以来",examples:[{zh:"大学毕业以来，我一直住在北京。",en:"I have lived in Beijing since graduation."},{zh:"今年以来，他进步很大。",en:"He has improved a lot since the beginning of this year."},{zh:"认识你以来，我学到了很多。",en:"I have learned a lot since knowing you."}],exercises:[{q:"填空：去年___，我一直在这里工作。",a:"以来",instr:"填空",instrEn:"Fill in the blank",body:"去年___，我一直在这里工作。"},{q:"翻译：He has improved a lot since this year began.",a:"今年以来，他进步很大。",instr:"翻译",instrEn:"Translate",body:"He has improved a lot since this year began."},{q:"排序：以来 / 认识你 / 很开心 / 我",a:"认识你以来，我很开心。",instr:"排序",instrEn:"Reorder the words",body:"以来 / 认识你 / 很开心 / 我"}],note:"常和“一直、已经”等搭配。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Often pairs with 一直/已经.",typeEn:"Time"},{id:"5.2.2",name:"“临”表示接近某个时间/事情",pinyin:"lín",type:"介词性动词",explainEn:"Use 临 before a time/event to mean “just before / when approaching”.",structure:"临 + 时间/事件",examples:[{zh:"临出门时，妈妈又提醒了我一次。",en:"Just before I went out, Mom reminded me again."},{zh:"临考试前，他有点儿紧张。",en:"Just before the exam, he was a little nervous."},{zh:"临下班时，经理来了。",en:"The manager came just before the end of work."}],exercises:[{q:"填空：___出门时，他发现忘了手机。",a:"临",instr:"填空",instrEn:"Fill in the blank",body:"___出门时，他发现忘了手机。"},{q:"翻译：just before the exam",a:"临考试前",instr:"翻译",instrEn:"Translate",body:"just before the exam"},{q:"排序：临 / 下班 / 他 / 接到 / 电话",a:"临下班，他接到电话。",instr:"排序",instrEn:"Reorder the words",body:"临 / 下班 / 他 / 接到 / 电话"}],note:"常见：临走、临出门、临考试。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Common: 临走, 临出门, 临考试.",typeEn:"Coverb"},{id:"5.2.3",name:"副词“立刻”表示马上",pinyin:"lìkè",type:"副词",explainEn:"Use 立刻 to mean “immediately / right away”.",structure:"立刻 + V",examples:[{zh:"听到消息后，他立刻给我打电话。",en:"After hearing the news, he called me immediately."},{zh:"请立刻停止。",en:"Please stop immediately."},{zh:"我一到家就立刻开始做饭。",en:"As soon as I got home, I started cooking right away."}],exercises:[{q:"填空：请___回来。",a:"立刻",instr:"填空",instrEn:"Fill in the blank",body:"请___回来。"},{q:"翻译：He called me immediately.",a:"他立刻给我打电话。",instr:"翻译",instrEn:"Translate",body:"He called me immediately."},{q:"选择：表示“马上”用（立刻 / 逐步）。",a:"立刻",instr:"选择",instrEn:"Choose",body:"表示“马上”用（立刻 / 逐步）。"}],note:"和“马上”接近，“立刻”稍正式。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Close to 马上; 立刻 is slightly more formal.",typeEn:"Adverb"}]},{num:3,title:"人生有选择，一切可改变",points:[{id:"5.3.1",name:"动词“包括”",pinyin:"bāokuò",type:"动词",explainEn:"Use 包括 to mean “include / including”.",structure:"整体 + 包括 + 部分",examples:[{zh:"费用包括早餐。",en:"The fee includes breakfast."},{zh:"参加的人包括老师和学生。",en:"The participants include teachers and students."},{zh:"这个计划包括三个部分。",en:"This plan includes three parts."}],exercises:[{q:"填空：费用___早餐。",a:"包括",instr:"填空",instrEn:"Fill in the blank",body:"费用___早餐。"},{q:"翻译：The plan includes three parts.",a:"这个计划包括三个部分。",instr:"翻译",instrEn:"Translate",body:"The plan includes three parts."},{q:"排序：老师 / 包括 / 参加的人 / 和学生",a:"参加的人包括老师和学生。",instr:"排序",instrEn:"Reorder the words",body:"老师 / 包括 / 参加的人 / 和学生"}],note:"“包括”后面列出整体中的成员或部分。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"包括 lists members or parts of a whole.",typeEn:"Verb"},{id:"5.3.2",name:"代词“各自”",pinyin:"gèzì",type:"代词",explainEn:"Use 各自 to mean “each person’s own / separately”.",structure:"各自 + V / 各自的 + N",examples:[{zh:"大家各自准备自己的材料。",en:"Everyone prepares their own materials."},{zh:"我们回到各自的房间。",en:"We returned to our own rooms."},{zh:"两个人各自有不同的想法。",en:"The two people each have different ideas."}],exercises:[{q:"填空：大家___完成自己的工作。",a:"各自",instr:"填空",instrEn:"Fill in the blank",body:"大家___完成自己的工作。"},{q:"翻译：We returned to our own rooms.",a:"我们回到各自的房间。",instr:"翻译",instrEn:"Translate",body:"We returned to our own rooms."},{q:"排序：各自 / 有 / 他们 / 想法",a:"他们各自有想法。",instr:"排序",instrEn:"Reorder the words",body:"各自 / 有 / 他们 / 想法"}],note:"“各自”强调每个人/每一方自己。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"各自 stresses each person's/side's own.",typeEn:"Pronoun"},{id:"5.3.3",name:"否定词“勿”",pinyin:"wù",type:"书面否定",explainEn:"Use 勿 as a formal written “do not”.",structure:"勿 + V",examples:[{zh:"请勿吸烟。",en:"Please do not smoke."},{zh:"请勿停车。",en:"No parking."},{zh:"请勿大声说话。",en:"Please do not speak loudly."}],exercises:[{q:"填空：请___吸烟。",a:"勿",instr:"填空",instrEn:"Fill in the blank",body:"请___吸烟。"},{q:"翻译：No parking.",a:"请勿停车。",instr:"翻译",instrEn:"Translate",body:"No parking."},{q:"把“不要大声说话”改成书面提示。",a:"请勿大声说话。"}],note:"常见于通知、标志和正式书面语。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Common in notices, signs and formal writing.",typeEn:"Formal negation"},{id:"5.3.4",name:"名词/副词“时刻”",pinyin:"shíkè",type:"时间表达",explainEn:"Use 时刻 to mean “moment”; as an adverb it can mean “at all times”.",structure:"重要时刻；时刻 + V",examples:[{zh:"这是一个重要时刻。",en:"This is an important moment."},{zh:"我们要时刻注意安全。",en:"We must pay attention to safety at all times."},{zh:"他时刻记着家人的话。",en:"He always keeps his family's words in mind."}],exercises:[{q:"填空：我们要___注意安全。",a:"时刻",instr:"填空",instrEn:"Fill in the blank",body:"我们要___注意安全。"},{q:"翻译：This is an important moment.",a:"这是一个重要时刻。",instr:"翻译",instrEn:"Translate",body:"This is an important moment."},{q:"选择：“always pay attention”可说（时刻 / 一旦）注意。",a:"时刻",instr:"选择",instrEn:"Choose",body:"“always pay attention”可说（时刻 / 一旦）注意。"}],note:"作副词时表示“随时、一直”。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:'As an adverb it means "at any time / all along".',typeEn:"Time"}]},{num:4,title:"子路背米",points:[{id:"5.4.1",name:"“至今”表示到现在",pinyin:"zhìjīn",type:"时间副词",explainEn:"Use 至今 to mean “up to now / to this day”.",structure:"至今 + 仍/还/没有…",examples:[{zh:"这件事至今没有解决。",en:"This matter has not been solved to this day."},{zh:"他离开十年了，至今没有回来。",en:"He left ten years ago and still has not returned."},{zh:"这个故事流传至今。",en:"This story has been passed down to the present."}],exercises:[{q:"填空：问题___没有解决。",a:"至今",instr:"填空",instrEn:"Fill in the blank",body:"问题___没有解决。"},{q:"翻译：This story has been passed down to the present.",a:"这个故事流传至今。",instr:"翻译",instrEn:"Translate",body:"This story has been passed down to the present."},{q:"排序：至今 / 他 / 没 / 回来",a:"他至今没回来。",instr:"排序",instrEn:"Reorder the words",body:"至今 / 他 / 没 / 回来"}],note:"较书面，常和“仍、还、没有”搭配。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Rather formal; pairs with 仍/还/没有.",typeEn:"Time adverb"},{id:"5.4.2",name:"量词“顶”",pinyin:"dǐng",type:"量词",explainEn:"Use 顶 as a measure word for hats, tents and some things with a top.",structure:"一顶 + 帽子/帐篷",examples:[{zh:"我买了一顶帽子。",en:"I bought a hat."},{zh:"山下有三顶帐篷。",en:"There are three tents at the foot of the mountain."},{zh:"这顶帽子很适合你。",en:"This hat suits you well."}],exercises:[{q:"填空：一___帽子",a:"顶",instr:"填空",instrEn:"Fill in the blank",body:"一___帽子"},{q:"翻译：three tents",a:"三顶帐篷",instr:"翻译",instrEn:"Translate",body:"three tents"},{q:"选择：帽子的量词是（顶 / 根）。",a:"顶",instr:"选择",instrEn:"Choose",body:"帽子的量词是（顶 / 根）。"}],note:"HSK5量词语言点之一。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"One of the HSK5 measure-word points.",typeEn:"Measure word"},{id:"5.4.3",name:"“得很 / 得不行 / 得不得了”表示程度很高",pinyin:"de hěn / de bùxíng / de bùdéliǎo",type:"程度补语",explainEn:"Use these after adjectives/verbs to mean “extremely / very”.",structure:"Adj/V + 得很/不行/不得了",examples:[{zh:"今天热得很。",en:"It is very hot today."},{zh:"我累得不行了。",en:"I am extremely tired."},{zh:"孩子高兴得不得了。",en:"The child is extremely happy."}],exercises:[{q:"填空：我累得___了。",a:"不行",instr:"填空",instrEn:"Fill in the blank",body:"我累得___了。"},{q:"翻译：The child is extremely happy.",a:"孩子高兴得不得了。",instr:"翻译",instrEn:"Translate",body:"The child is extremely happy."},{q:"用“得很”改写：今天非常冷。",a:"今天冷得很。",instr:"用“得很”改写",instrEn:"Rewrite with 得很",body:"今天非常冷。"}],note:"都是口语程度表达；“不得了”语气最强。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"All are colloquial degree markers; 不得了 is the strongest.",typeEn:"Degree complement"},{id:"5.4.4",name:"“不但不/没……，反而……”",pinyin:"bùdàn bù/méi ... fǎn'ér ...",type:"递进/反转复句",explainEn:"Use 不但不/没…反而… when the result is opposite and even stronger than expected.",structure:"不但不/没 + A，反而 + B",examples:[{zh:"他不但没生气，反而笑了。",en:"He not only did not get angry, but instead laughed."},{zh:"雨不但没停，反而更大了。",en:"The rain did not stop; instead, it became heavier."},{zh:"他不但不帮忙，反而添麻烦。",en:"He not only did not help, but caused more trouble."}],exercises:[{q:"填空：他不但没生气，___笑了。",a:"反而",instr:"填空",instrEn:"Fill in the blank",body:"他不但没生气，___笑了。"},{q:"翻译：The rain got even heavier instead.",a:"雨不但没停，反而更大了。",instr:"翻译",instrEn:"Translate",body:"The rain got even heavier instead."},{q:"连接：他不帮忙。他还添麻烦。",a:"他不但不帮忙，反而添麻烦。",instr:"连接",instrEn:"Join the sentences",body:"他不帮忙。他还添麻烦。"}],note:"“反而”表示与正常预期相反。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"反而 marks the opposite of what's normally expected.",typeEn:"Progressive / Reversal"}]},{num:5,title:"济南的泉水",points:[{id:"5.5.1",name:"“……，从而……”表示前因后果/目的结果",pinyin:"cóng'ér",type:"连接词",explainEn:"Use 从而 to introduce a result that comes from the previous action or situation.",structure:"A，从而 + B",examples:[{zh:"他每天练习，从而提高了汉语水平。",en:"He practices every day, thereby improving his Chinese."},{zh:"我们改进方法，从而提高效率。",en:"We improved the method and thereby increased efficiency."},{zh:"多运动可以改善睡眠，从而让身体更健康。",en:"Exercise can improve sleep and thus make the body healthier."}],exercises:[{q:"填空：他努力学习，___取得了进步。",a:"从而",instr:"填空",instrEn:"Fill in the blank",body:"他努力学习，___取得了进步。"},{q:"翻译：We improved efficiency as a result.",a:"我们从而提高了效率。",instr:"翻译",instrEn:"Translate",body:"We improved efficiency as a result."},{q:"用“从而”连接：我们改变方法。效率提高了。",a:"我们改变了方法，从而提高了效率。",instr:"用“从而”连接",instrEn:"Join with 从而",body:"我们改变方法。效率提高了。"}],note:"较书面，强调前面的行为带来后面的结果。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Rather formal; stresses that the earlier act leads to the later result.",typeEn:"Connective"},{id:"5.5.2",name:"介词“于”",pinyin:"yú",type:"书面介词",explainEn:"Use 于 in formal Chinese for “in / at / to / than”, depending on context.",structure:"V/Adj + 于 + N",examples:[{zh:"会议将于明天举行。",en:"The meeting will be held tomorrow."},{zh:"他出生于北京。",en:"He was born in Beijing."},{zh:"这个数字高于去年。",en:"This number is higher than last year's."}],exercises:[{q:"填空：会议将___周五举行。",a:"于",instr:"填空",instrEn:"Fill in the blank",body:"会议将___周五举行。"},{q:"翻译：He was born in Beijing.",a:"他出生于北京。",instr:"翻译",instrEn:"Translate",body:"He was born in Beijing."},{q:"选择：“higher than last year”可说“高（于 / 靠）去年”。",a:"于",instr:"选择",instrEn:"Choose",body:"“higher than last year”可说“高（于 / 靠）去年”。"}],note:"常见于书面语：位于、由于、对于、高于、低于等。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Common in writing: 位于, 由于, 对于, 高于, 低于.",typeEn:"Formal preposition"},{id:"5.5.3",name:"动词“为（wéi）”表示“是/成为/作为”",pinyin:"wéi",type:"书面动词",explainEn:"Use 为 (wéi) in formal Chinese to mean “be / become / serve as”.",structure:"以…为…；成为/视为",examples:[{zh:"我们以服务客人为目标。",en:"We take serving customers as our goal."},{zh:"他被选为班长。",en:"He was chosen as class monitor."},{zh:"健康最为重要。",en:"Health is the most important."}],exercises:[{q:"填空：他被选___班长。",a:"为",instr:"填空",instrEn:"Fill in the blank",body:"他被选___班长。"},{q:"翻译：We take health as our goal.",a:"我们以健康为目标。",instr:"翻译",instrEn:"Translate",body:"We take health as our goal."},{q:"选择：“be chosen as”用“选（为 / 于）”。",a:"为",instr:"选择",instrEn:"Choose",body:"“be chosen as”用“选（为 / 于）”。"}],note:"读 wéi；常见结构：以A为B、选为、认为。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Read wéi; common: 以A为B, 选为, 认为.",typeEn:"Formal verb"},{id:"5.5.4",name:"趋向补语“起来”表示开始/总体感觉",pinyin:"qǐlái",type:"趋向补语引申",explainEn:"Use 起来 to show something starts, or to give an overall impression.",structure:"V/Adj + 起来；看/听/吃起来",examples:[{zh:"天气慢慢热起来了。",en:"The weather is getting warmer."},{zh:"这件衣服看起来不错。",en:"This clothing looks good."},{zh:"这个菜吃起来很香。",en:"This dish tastes good."}],exercises:[{q:"填空：天气暖___了。",a:"起来",instr:"填空",instrEn:"Fill in the blank",body:"天气暖___了。"},{q:"翻译：This clothing looks good.",a:"这件衣服看起来不错。",instr:"翻译",instrEn:"Translate",body:"This clothing looks good."},{q:"选择：“tastes good”可说“吃（起来 / 出来）不错”。",a:"起来",instr:"选择",instrEn:"Choose",body:"“tastes good”可说“吃（起来 / 出来）不错”。"}],note:"常见：看起来、听起来、说起来、热起来。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Common: 看起来, 听起来, 说起来, 热起来.",typeEn:"Directional (fig.)"}]},{num:6,title:"除夕的由来",points:[{id:"5.6.1",name:"介词“替”表示代替/为某人",pinyin:"tì",type:"介词",explainEn:"Use 替 to mean “for / instead of someone”.",structure:"替 + 人 + V",examples:[{zh:"我替你去一趟吧。",en:"Let me go instead of you."},{zh:"谢谢你替我照顾孩子。",en:"Thank you for taking care of the child for me."},{zh:"他替同事完成了工作。",en:"He finished the work for his colleague."}],exercises:[{q:"填空：我___你去吧。",a:"替",instr:"填空",instrEn:"Fill in the blank",body:"我___你去吧。"},{q:"翻译：Thank you for helping me.",a:"谢谢你替我帮忙。",instr:"翻译",instrEn:"Translate",body:"Thank you for helping me."},{q:"排序：替 / 他 / 同事 / 工作 / 做了",a:"他替同事做了工作。",instr:"排序",instrEn:"Reorder the words",body:"替 / 他 / 同事 / 工作 / 做了"}],note:"和“帮、给”有时接近，但“替”强调代替某人。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Close to 帮/给, but 替 stresses doing it in someone's place.",typeEn:"Preposition"},{id:"5.6.2",name:"副词“说不定”",pinyin:"shuōbudìng",type:"副词",explainEn:"Use 说不定 to mean “maybe / perhaps; it is hard to say”.",structure:"说不定 + 句子",examples:[{zh:"明天说不定会下雨。",en:"It may rain tomorrow."},{zh:"他现在出发，说不定还能赶上。",en:"If he leaves now, maybe he can still make it."},{zh:"别担心，说不定事情会变好。",en:"Don't worry; things may get better."}],exercises:[{q:"填空：明天___会下雨。",a:"说不定",instr:"填空",instrEn:"Fill in the blank",body:"明天___会下雨。"},{q:"翻译：Maybe he can still make it.",a:"说不定他还能赶上。",instr:"翻译",instrEn:"Translate",body:"Maybe he can still make it."},{q:"选择：表示不确定可能用（说不定 / 至今）。",a:"说不定",instr:"选择",instrEn:"Choose",body:"表示不确定可能用（说不定 / 至今）。"}],note:"口语感较强，表示可能性不确定。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Fairly colloquial; expresses uncertain possibility.",typeEn:"Adverb"},{id:"5.6.3",name:"“像……似的 / ……似的”表示相似",pinyin:"shìde",type:"比喻结构",explainEn:"Use 似的 after a noun/phrase to mean “like / as if”.",structure:"像 + N + 似的；N + 似的",examples:[{zh:"孩子像小鸟似的跑了出去。",en:"The child ran out like a little bird."},{zh:"雨下得跟倒水似的。",en:"The rain poured as if water were being dumped."},{zh:"他什么都没听见似的。",en:"He acted as if he had heard nothing."}],exercises:[{q:"填空：他像没听见___。",a:"似的",instr:"填空",instrEn:"Fill in the blank",body:"他像没听见___。"},{q:"翻译：The child ran out like a bird.",a:"孩子像小鸟似的跑了出去。",instr:"翻译",instrEn:"Translate",body:"The child ran out like a bird."},{q:"选择：“like a child”可说“像孩子（似的 / 以来）”。",a:"似的",instr:"选择",instrEn:"Choose",body:"“like a child”可说“像孩子（似的 / 以来）”。"}],note:"“似”在这里通常读 shì。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Here 似 is usually read shì.",typeEn:"Simile structure"},{id:"5.6.4",name:"副词“纷纷”表示许多人先后做同一动作",pinyin:"fēnfēn",type:"副词",explainEn:"Use 纷纷 when many people/things do the same kind of action one after another.",structure:"复数主语 + 纷纷 + V",examples:[{zh:"大家纷纷表示同意。",en:"Everyone expressed agreement one after another."},{zh:"听到消息后，人们纷纷赶来。",en:"After hearing the news, people came one after another."},{zh:"学生们纷纷举手回答。",en:"The students raised their hands one after another."}],exercises:[{q:"填空：大家___表示支持。",a:"纷纷",instr:"填空",instrEn:"Fill in the blank",body:"大家___表示支持。"},{q:"翻译：People came one after another.",a:"人们纷纷赶来。",instr:"翻译",instrEn:"Translate",body:"People came one after another."},{q:"选择：很多人先后行动用（纷纷 / 各自）。",a:"纷纷",instr:"选择",instrEn:"Choose",body:"很多人先后行动用（纷纷 / 各自）。"}],note:"主语一般是复数或群体。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"The subject is usually plural or a group.",typeEn:"Adverb"}]},{num:7,title:"成语故事两则",points:[{id:"5.7.1",name:"副词“瞎”表示没有目的/不正确地做",pinyin:"xiā",type:"副词（口语）",explainEn:"Use 瞎 before a verb to mean doing something blindly, carelessly, or without reason.",structure:"瞎 + V",examples:[{zh:"别瞎说。",en:"Don't talk nonsense."},{zh:"你别瞎担心。",en:"Don't worry for no reason."},{zh:"不知道就别瞎猜。",en:"Don't guess blindly if you don't know."}],exercises:[{q:"填空：别___说。",a:"瞎",instr:"填空",instrEn:"Fill in the blank",body:"别___说。"},{q:"翻译：Don't worry for no reason.",a:"别瞎担心。",instr:"翻译",instrEn:"Translate",body:"Don't worry for no reason."},{q:"选择：表示“blindly guess”可说（瞎猜 / 立刻猜）。",a:"瞎猜",instr:"选择",instrEn:"Choose",body:"表示“blindly guess”可说（瞎猜 / 立刻猜）。"}],note:"口语，有时语气较直接。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Colloquial, sometimes rather blunt.",typeEn:"Adverb (colloquial)"},{id:"5.7.2",name:"副词“分别”表示各自/逐一",pinyin:"fēnbié",type:"副词",explainEn:"Use 分别 to mean “separately / respectively”.",structure:"主语 + 分别 + V",examples:[{zh:"两位老师分别介绍了自己的课程。",en:"The two teachers introduced their courses separately."},{zh:"我们分别住在北京和上海。",en:"We live in Beijing and Shanghai respectively."},{zh:"请分别回答这三个问题。",en:"Please answer the three questions separately."}],exercises:[{q:"填空：他们___介绍了自己。",a:"分别",instr:"填空",instrEn:"Fill in the blank",body:"他们___介绍了自己。"},{q:"翻译：Please answer separately.",a:"请分别回答。",instr:"翻译",instrEn:"Translate",body:"Please answer separately."},{q:"排序：分别 / 北京和上海 / 他们 / 住在",a:"他们分别住在北京和上海。",instr:"排序",instrEn:"Reorder the words",body:"分别 / 北京和上海 / 他们 / 住在"}],note:"“分别”强调一个一个、各自对应。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"分别 stresses one by one / each respectively.",typeEn:"Adverb"},{id:"5.7.3",name:"量词“根”",pinyin:"gēn",type:"量词",explainEn:"Use 根 for long, thin objects such as sticks, ropes, hairs.",structure:"一根 + 绳子/头发/棍子",examples:[{zh:"桌上有一根绳子。",en:"There is a rope on the table."},{zh:"我发现了一根白头发。",en:"I found a white hair."},{zh:"他拿着一根棍子。",en:"He is holding a stick."}],exercises:[{q:"填空：一___绳子",a:"根",instr:"填空",instrEn:"Fill in the blank",body:"一___绳子"},{q:"翻译：a white hair",a:"一根白头发",instr:"翻译",instrEn:"Translate",body:"a white hair"},{q:"选择：绳子的量词是（根 / 顶）。",a:"根",instr:"选择",instrEn:"Choose",body:"绳子的量词是（根 / 顶）。"}],note:"HSK5量词语言点之一。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"One of the HSK5 measure-word points.",typeEn:"Measure word"},{id:"5.7.4",name:"副词“便”表示“就”",pinyin:"biàn",type:"副词（书面）",explainEn:"Use 便 in formal/literary Chinese like 就: “then / immediately”.",structure:"条件/动作 + 便 + 结果",examples:[{zh:"他吃完饭便出门了。",en:"He went out right after eating."},{zh:"有问题便给我打电话。",en:"Call me if there is a problem."},{zh:"听到这个消息，他便笑了。",en:"On hearing the news, he smiled."}],exercises:[{q:"填空：吃完饭他___走了。",a:"便",instr:"填空",instrEn:"Fill in the blank",body:"吃完饭他___走了。"},{q:"翻译：Call me if there is a problem.",a:"有问题便给我打电话。",instr:"翻译",instrEn:"Translate",body:"Call me if there is a problem."},{q:"把“他一到家就休息”改得更书面。",a:"他一到家便休息。"}],note:"“便”比“就”更书面。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"便 is more formal than 就.",typeEn:"Adverb (formal)"}]},{num:8,title:"“朝三暮四”的古今义",points:[{id:"5.8.1",name:"副词“倒”表示与预期不同/轻微转折",pinyin:"dào",type:"副词",explainEn:"Use 倒 to show a mild contrast or an unexpected opinion.",structure:"主语 + 倒 + 谓语",examples:[{zh:"这个办法倒不错。",en:"This method is actually pretty good."},{zh:"他年纪不大，经验倒不少。",en:"He is not old, but he has quite a lot of experience."},{zh:"我不累，倒是有点儿饿。",en:"I am not tired; actually I am a little hungry."}],exercises:[{q:"填空：这个办法___不错。",a:"倒",instr:"填空",instrEn:"Fill in the blank",body:"这个办法___不错。"},{q:"翻译：I'm not tired; I'm actually hungry.",a:"我不累，倒有点儿饿。",instr:"翻译",instrEn:"Translate",body:"I'm not tired; I'm actually hungry."},{q:"选择：表示轻微反差可用（倒 / 自从）。",a:"倒",instr:"选择",instrEn:"Choose",body:"表示轻微反差可用（倒 / 自从）。"}],note:"常有“没想到/相反”的感觉，语气比“却”柔和。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:'Carries "unexpectedly/contrary", softer than 却.',typeEn:"Adverb"},{id:"5.8.2",name:"“V来V去”表示动作反复",pinyin:"V lái V qù",type:"动词结构",explainEn:"Use V来V去 to show the same action repeats again and again.",structure:"V + 来 + V + 去",examples:[{zh:"我想来想去，还是决定去。",en:"I thought it over and over and decided to go."},{zh:"他走来走去，看起来很着急。",en:"He walked back and forth and looked anxious."},{zh:"大家说来说去还是这个问题。",en:"People kept talking and still came back to the same issue."}],exercises:[{q:"填空：我想___想___。",a:"来；去",instr:"填空",instrEn:"Fill in the blank",body:"我想___想___。"},{q:"翻译：He walked back and forth.",a:"他走来走去。",instr:"翻译",instrEn:"Translate",body:"He walked back and forth."},{q:"把“看”组成“反复看”的结构。",a:"看来看去"}],note:"常见：想来想去、说来说去、看来看去、走来走去。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Common: 想来想去, 说来说去, 看来看去, 走来走去.",typeEn:"Verb structure"},{id:"5.8.3",name:"连词“要不”表示建议或“否则”",pinyin:"yàobù",type:"连词",explainEn:"Use 要不 for “how about… / otherwise”.",structure:"要不 + 建议；A，要不 + 后果",examples:[{zh:"要不我们明天再去吧。",en:"How about we go tomorrow instead?"},{zh:"你累了，要不休息一下？",en:"You're tired; how about taking a rest?"},{zh:"快点儿，要不就迟到了。",en:"Hurry, otherwise we will be late."}],exercises:[{q:"填空：___我们坐地铁吧。",a:"要不",instr:"填空",instrEn:"Fill in the blank",body:"___我们坐地铁吧。"},{q:"翻译：Hurry, otherwise we'll be late.",a:"快点儿，要不就迟到了。",instr:"翻译",instrEn:"Translate",body:"Hurry, otherwise we'll be late."},{q:"选择：提出建议可用（要不 / 至今）。",a:"要不",instr:"选择",instrEn:"Choose",body:"提出建议可用（要不 / 至今）。"}],note:"口语很常见；既可提建议，也可表示“否则”。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:'Very colloquial; can suggest, or mean "otherwise".',typeEn:"Conjunction"},{id:"5.8.4",name:"“彼此”和“互相”",pinyin:"bǐcǐ / hùxiāng",type:"代词/副词",explainEn:"彼此 means “each other” as a pronoun. 互相 is an adverb meaning “mutually”.",structure:"彼此 + V/N；互相 + V",examples:[{zh:"我们应该互相帮助。",en:"We should help each other."},{zh:"两个人彼此都很了解。",en:"The two people know each other well."},{zh:"朋友之间要彼此信任。",en:"Friends should trust each other."}],exercises:[{q:"填空：我们应该___帮助。",a:"互相",instr:"填空",instrEn:"Fill in the blank",body:"我们应该___帮助。"},{q:"翻译：They know each other well.",a:"他们彼此很了解。",instr:"翻译",instrEn:"Translate",body:"They know each other well."},{q:"选择：“each other”作副词修饰“帮助”用（互相 / 彼此的）。",a:"互相",instr:"选择",instrEn:"Choose",body:"“each other”作副词修饰“帮助”用（互相 / 彼此的）。"}],note:"“互相”不能直接作定语；“彼此”可作主语/宾语/定语。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"互相 can't be a modifier; 彼此 can be subject/object/modifier.",typeEn:"Pronoun / Adverb"}]},{num:9,title:"别样鲁迅",points:[{id:"5.9.1",name:"动词“算”表示可以看作/勉强算",pinyin:"suàn",type:"动词",explainEn:"Use 算 to mean “count as / be considered / can be regarded as”.",structure:"算 + N/Adj；算是 + N",examples:[{zh:"这次算成功了。",en:"This can be considered a success."},{zh:"他算是我的老朋友。",en:"He can be considered an old friend of mine."},{zh:"这个价格不算贵。",en:"This price is not considered expensive."}],exercises:[{q:"填空：这个价格不___贵。",a:"算",instr:"填空",instrEn:"Fill in the blank",body:"这个价格不___贵。"},{q:"翻译：He can be considered my old friend.",a:"他算是我的老朋友。",instr:"翻译",instrEn:"Translate",body:"He can be considered my old friend."},{q:"选择：“可以看作成功”可说“算（成功 / 从来）”。",a:"成功",instr:"选择",instrEn:"Choose",body:"“可以看作成功”可说“算（成功 / 从来）”。"}],note:"“算”常表示按某个标准判断。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"算 often means to judge by some standard.",typeEn:"Verb"},{id:"5.9.2",name:"介词“作为”",pinyin:"zuòwéi",type:"介词",explainEn:"Use 作为 to mean “as / in the role of”.",structure:"作为 + 身份/角色，……",examples:[{zh:"作为老师，他很有责任心。",en:"As a teacher, he is very responsible."},{zh:"我把这本书作为礼物送给你。",en:"I give you this book as a gift."},{zh:"作为朋友，我应该帮助你。",en:"As a friend, I should help you."}],exercises:[{q:"填空：___老师，他很认真。",a:"作为",instr:"填空",instrEn:"Fill in the blank",body:"___老师，他很认真。"},{q:"翻译：I gave it to you as a gift.",a:"我把它作为礼物送给你。",instr:"翻译",instrEn:"Translate",body:"I gave it to you as a gift."},{q:"排序：作为 / 朋友 / 我 / 帮你 / 应该",a:"作为朋友，我应该帮你。",instr:"排序",instrEn:"Reorder the words",body:"作为 / 朋友 / 我 / 帮你 / 应该"}],note:"可表示身份，也可表示用途。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Can mark a role/identity or a use/purpose.",typeEn:"Preposition"},{id:"5.9.3",name:"副词“曾经”",pinyin:"céngjīng",type:"副词",explainEn:"Use 曾经 to mean “once / formerly” for a past experience or state.",structure:"曾经 + V/Adj",examples:[{zh:"我曾经在上海工作过。",en:"I once worked in Shanghai."},{zh:"他曾经是老师。",en:"He used to be a teacher."},{zh:"我们曾经见过面。",en:"We have met before."}],exercises:[{q:"填空：我___去过那里。",a:"曾经",instr:"填空",instrEn:"Fill in the blank",body:"我___去过那里。"},{q:"翻译：He used to be a teacher.",a:"他曾经是老师。",instr:"翻译",instrEn:"Translate",body:"He used to be a teacher."},{q:"选择：过去经历用（曾经 / 立刻）。",a:"曾经",instr:"选择",instrEn:"Choose",body:"过去经历用（曾经 / 立刻）。"}],note:"常和“过”一起表示过去经历。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Often used with 过 for a past experience.",typeEn:"Adverb"}]},{num:10,title:"争论的奇迹",points:[{id:"5.10.1",name:"副词“毕竟”",pinyin:"bìjìng",type:"副词",explainEn:"Use 毕竟 to emphasize an important fact: “after all”.",structure:"毕竟 + 事实/理由",examples:[{zh:"他毕竟还是个孩子。",en:"After all, he is still a child."},{zh:"别怪他，毕竟这是第一次。",en:"Don't blame him; after all, this is his first time."},{zh:"这件事毕竟已经过去了。",en:"After all, this matter is already in the past."}],exercises:[{q:"填空：他___还是个孩子。",a:"毕竟",instr:"填空",instrEn:"Fill in the blank",body:"他___还是个孩子。"},{q:"翻译：After all, this is his first time.",a:"毕竟这是第一次。",instr:"翻译",instrEn:"Translate",body:"After all, this is his first time."},{q:"选择：“after all”用（毕竟 / 立刻）。",a:"毕竟",instr:"选择",instrEn:"Choose",body:"“after all”用（毕竟 / 立刻）。"}],note:"常用于解释、让步或提醒对方注意一个事实。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Used to explain, concede, or point out a fact.",typeEn:"Adverb"},{id:"5.10.2",name:"副词“逐渐”",pinyin:"zhújiàn",type:"副词",explainEn:"Use 逐渐 to mean “gradually”.",structure:"逐渐 + V/Adj",examples:[{zh:"天气逐渐暖和了。",en:"The weather gradually became warmer."},{zh:"他逐渐适应了新工作。",en:"He gradually adapted to the new job."},{zh:"我的汉语水平逐渐提高了。",en:"My Chinese gradually improved."}],exercises:[{q:"填空：天气___变冷。",a:"逐渐",instr:"填空",instrEn:"Fill in the blank",body:"天气___变冷。"},{q:"翻译：He gradually adapted.",a:"他逐渐适应了。",instr:"翻译",instrEn:"Translate",body:"He gradually adapted."},{q:"选择：“gradually”用（逐渐 / 立刻）。",a:"逐渐",instr:"选择",instrEn:"Choose",body:"“gradually”用（逐渐 / 立刻）。"}],note:"强调变化一步一步发生。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Stresses that change happens step by step.",typeEn:"Adverb"},{id:"5.10.3",name:"副词“或许”",pinyin:"huòxǔ",type:"副词",explainEn:"Use 或许 to mean “perhaps / maybe”.",structure:"或许 + 句子",examples:[{zh:"他或许已经知道了。",en:"Perhaps he already knows."},{zh:"明天或许会下雨。",en:"Maybe it will rain tomorrow."},{zh:"换个方法或许更好。",en:"Perhaps another method would be better."}],exercises:[{q:"填空：他___会来。",a:"或许",instr:"填空",instrEn:"Fill in the blank",body:"他___会来。"},{q:"翻译：Maybe it will rain tomorrow.",a:"明天或许会下雨。",instr:"翻译",instrEn:"Translate",body:"Maybe it will rain tomorrow."},{q:"选择：表示可能用（或许 / 至今）。",a:"或许",instr:"选择",instrEn:"Choose",body:"表示可能用（或许 / 至今）。"}],note:"与“也许”接近，稍书面。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Close to 也许, slightly more formal.",typeEn:"Adverb"}]},{num:11,title:"闹钟的危害",points:[{id:"5.11.1",name:"“来 / 过来”表示状态恢复或转变",pinyin:"lái / guòlái",type:"趋向补语引申",explainEn:"Use 来/过来 after some verbs to show a change or recovery.",structure:"V + 过来；醒/明白/反应 + 过来",examples:[{zh:"他终于醒过来了。",en:"He finally woke up."},{zh:"我一下子明白过来了。",en:"I suddenly understood."},{zh:"听了半天，我才反应过来。",en:"After listening for a while, I finally realized what was happening."}],exercises:[{q:"填空：我终于明白___了。",a:"过来",instr:"填空",instrEn:"Fill in the blank",body:"我终于明白___了。"},{q:"翻译：He finally woke up.",a:"他终于醒过来了。",instr:"翻译",instrEn:"Translate",body:"He finally woke up."},{q:"选择：“realize”常说“反应（过来 / 下去）”。",a:"过来",instr:"选择",instrEn:"Choose",body:"“realize”常说“反应（过来 / 下去）”。"}],note:"是趋向补语的引申用法，不一定表示真实移动。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"An extended directional use; not necessarily real movement.",typeEn:"Directional (fig.)"},{id:"5.11.2",name:"“所 + 动词”构成书面定语",pinyin:"suǒ + V",type:"所字结构",explainEn:"Use 所 + verb before 的 to form a formal modifier: “what/that which is…”.",structure:"所 + V + 的 + N / 所 + V",examples:[{zh:"这是我所了解的情况。",en:"This is the situation I know about."},{zh:"他所说的话很有道理。",en:"What he said makes sense."},{zh:"我们要解决所遇到的问题。",en:"We need to solve the problems we encounter."}],exercises:[{q:"填空：这是我___知道的。",a:"所",instr:"填空",instrEn:"Fill in the blank",body:"这是我___知道的。"},{q:"翻译：What he said makes sense.",a:"他所说的话很有道理。",instr:"翻译",instrEn:"Translate",body:"What he said makes sense."},{q:"排序：所 / 问题 / 我们 / 遇到的",a:"我们所遇到的问题。",instr:"排序",instrEn:"Reorder the words",body:"所 / 问题 / 我们 / 遇到的"}],note:"较书面；常见“所说、所想、所需要、所看到”。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Rather formal; e.g. 所说, 所想, 所需要, 所看到.",typeEn:"所-phrase"},{id:"5.11.3",name:"“相当 / 相当于”",pinyin:"xiāngdāng / xiāngdāngyú",type:"形容词/动词",explainEn:"相当 + adjective means “quite”. 相当于 means “be equivalent to”.",structure:"相当 + Adj；A 相当于 B",examples:[{zh:"这个问题相当复杂。",en:"This problem is quite complicated."},{zh:"一天的费用相当于我两天的工资。",en:"One day's cost is equivalent to two days of my salary."},{zh:"他的汉语相当不错。",en:"His Chinese is quite good."}],exercises:[{q:"填空：这个工作___难。",a:"相当",instr:"填空",instrEn:"Fill in the blank",body:"这个工作___难。"},{q:"翻译：A is equivalent to B.",a:"A相当于B。",instr:"翻译",instrEn:"Translate",body:"A is equivalent to B."},{q:"选择：“quite good”可说“相当（不错 / 于不错）”。",a:"不错",instr:"选择",instrEn:"Choose",body:"“quite good”可说“相当（不错 / 于不错）”。"}],note:"注意“相当”与“相当于”的结构不同。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Note that 相当 and 相当于 differ in structure.",typeEn:"Adjective / Verb"},{id:"5.11.4",name:"“数（shù）+ 量词”表示几个/若干",pinyin:"shù",type:"数词用法",explainEn:"Use 数 (shù) before a measure word to mean “several”.",structure:"数 + 量词 + N",examples:[{zh:"我们等了数小时。",en:"We waited for several hours."},{zh:"数百人参加了活动。",en:"Several hundred people attended the event."},{zh:"他已经连续工作了数天。",en:"He has worked for several days in a row."}],exercises:[{q:"填空：我们等了___小时。",a:"数",instr:"填空",instrEn:"Fill in the blank",body:"我们等了___小时。"},{q:"翻译：several days",a:"数天",instr:"翻译",instrEn:"Translate",body:"several days"},{q:"选择：“several hundred people”可说（数百人 / 数个人百）。",a:"数百人",instr:"选择",instrEn:"Choose",body:"“several hundred people”可说（数百人 / 数个人百）。"}],note:"这里读 shù，不是 shǔ“数数”。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Read shù here, not shǔ (as in 数数, to count).",typeEn:"Numeral usage"}]},{num:12,title:"海外用户玩儿微信",points:[{id:"5.12.1",name:"连词“以及”",pinyin:"yǐjí",type:"连词",explainEn:"Use 以及 to connect nouns or phrases, similar to “and / as well as”; it is formal.",structure:"A、B以及C",examples:[{zh:"老师、学生以及家长都参加了。",en:"Teachers, students, and parents all attended."},{zh:"我们讨论了时间、地点以及费用。",en:"We discussed the time, place, and cost."},{zh:"健康以及安全都很重要。",en:"Health as well as safety is important."}],exercises:[{q:"填空：时间、地点___费用都要确定。",a:"以及",instr:"填空",instrEn:"Fill in the blank",body:"时间、地点___费用都要确定。"},{q:"翻译：Teachers, students, and parents all attended.",a:"老师、学生以及家长都参加了。",instr:"翻译",instrEn:"Translate",body:"Teachers, students, and parents all attended."},{q:"选择：较书面的“and”可用（以及 / 要不）。",a:"以及",instr:"选择",instrEn:"Choose",body:"较书面的“and”可用（以及 / 要不）。"}],note:"多用于书面列举，通常连接最后一项。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Mostly for written lists, usually joining the last item.",typeEn:"Conjunction"},{id:"5.12.2",name:"“……的程度 / 到……程度”",pinyin:"chéngdù",type:"程度表达",explainEn:"Use 程度 to talk about how serious/high/strong something is: “degree / extent”.",structure:"Adj + 的程度；到 + … + 的程度",examples:[{zh:"问题已经到了很严重的程度。",en:"The problem has reached a serious level."},{zh:"我没想到他忙到这个程度。",en:"I didn't expect him to be this busy."},{zh:"污染的程度正在下降。",en:"The level of pollution is decreasing."}],exercises:[{q:"填空：问题到了很严重的___。",a:"程度",instr:"填空",instrEn:"Fill in the blank",body:"问题到了很严重的___。"},{q:"翻译：He is busy to this degree.",a:"他忙到这个程度。",instr:"翻译",instrEn:"Translate",body:"He is busy to this degree."},{q:"排序：程度 / 污染 / 的 / 不严重",a:"污染的程度不严重。",instr:"排序",instrEn:"Reorder the words",body:"程度 / 污染 / 的 / 不严重"}],note:"常见“达到……程度、严重程度、一定程度上”。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Common: 达到…程度, 严重程度, 一定程度上.",typeEn:"Degree"}]},{num:13,title:"锯掉生活的“筐底”",points:[{id:"5.13.1",name:"“（更）何况”表示“更不用说”",pinyin:"(gèng) hékuàng",type:"递进复句",explainEn:"Use 何况 / 更何况 for “let alone / much less”.",structure:"A都…，更何况B呢；何况 + 更强理由",examples:[{zh:"这么简单的题我都会，更何况老师呢？",en:"Even I can do such an easy question, let alone the teacher."},{zh:"他连饭都没时间吃，更何况出去玩。",en:"He has no time even to eat, let alone go out."},{zh:"今天本来就忙，何况又来了这么多客人。",en:"We were already busy, not to mention so many guests came."}],exercises:[{q:"填空：我都会，___老师呢？",a:"更何况",instr:"填空",instrEn:"Fill in the blank",body:"我都会，___老师呢？"},{q:"翻译：He has no time to eat, let alone go out.",a:"他连饭都没时间吃，更何况出去玩。",instr:"翻译",instrEn:"Translate",body:"He has no time to eat, let alone go out."},{q:"选择：“let alone”用（何况 / 至今）。",a:"何况",instr:"选择",instrEn:"Choose",body:"“let alone”用（何况 / 至今）。"}],note:"后一情况通常比前面更明显、更不用说。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:'The latter case is even more obvious, "let alone".',typeEn:"Progressive clause"},{id:"5.13.2",name:"副词“何必”表示“没有必要”",pinyin:"hébì",type:"反问副词",explainEn:"Use 何必 to mean “why bother / there is no need to…”.",structure:"何必 + V + 呢？",examples:[{zh:"这么近，何必开车呢？",en:"It's so close; why bother driving?"},{zh:"有话慢慢说，何必生气呢？",en:"Talk it out calmly; why get angry?"},{zh:"你何必亲自去一趟？",en:"Why do you need to go in person?"}],exercises:[{q:"填空：这么简单，___担心呢？",a:"何必",instr:"填空",instrEn:"Fill in the blank",body:"这么简单，___担心呢？"},{q:"翻译：Why bother driving?",a:"何必开车呢？",instr:"翻译",instrEn:"Translate",body:"Why bother driving?"},{q:"改写：没有必要生气。（用“何必”）",a:"何必生气呢？",instr:"改写",instrEn:"Rewrite",body:"没有必要生气。（用“何必”）"}],note:"常用反问形式，意思是“没必要”。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:`Often a rhetorical question meaning "there's no need".`,typeEn:"Rhetorical adverb"},{id:"5.13.3",name:"“多亏（了）”表示幸好有某个帮助/条件",pinyin:"duōkuī",type:"介词性动词",explainEn:"Use 多亏（了） to mean “thanks to / fortunately because of”.",structure:"多亏（了）+ 人/事，才/否则…",examples:[{zh:"多亏了你，我才按时完成。",en:"Thanks to you, I finished on time."},{zh:"多亏天气好，活动很顺利。",en:"Thanks to the good weather, the event went smoothly."},{zh:"多亏你提醒我，不然我就忘了。",en:"Thanks for reminding me; otherwise I would have forgotten."}],exercises:[{q:"填空：___你提醒，我才没忘。",a:"多亏",instr:"填空",instrEn:"Fill in the blank",body:"___你提醒，我才没忘。"},{q:"翻译：Thanks to you, I finished on time.",a:"多亏了你，我才按时完成。",instr:"翻译",instrEn:"Translate",body:"Thanks to you, I finished on time."},{q:"补全：多亏你帮忙，___我们完成得很快。",a:"所以/我们",instr:"补全",instrEn:"Complete the sentence",body:"多亏你帮忙，___我们完成得很快。"}],note:"通常说的是积极条件带来的好结果。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Usually a helpful condition leading to a good result.",typeEn:"Coverb"}]},{num:14,title:"北京的四合院",points:[{id:"5.14.1",name:"“所谓”表示“所说的/所谓的”",pinyin:"suǒwèi",type:"定语/书面表达",explainEn:"Use 所谓 to mean “so-called / what is called”.",structure:"所谓（的）+ N；所谓…就是…",examples:[{zh:"所谓成功，不只是赚很多钱。",en:"So-called success is not just making a lot of money."},{zh:"这就是所谓的机会。",en:"This is what is called an opportunity."},{zh:"他所谓的办法其实很简单。",en:"His so-called method is actually simple."}],exercises:[{q:"填空：这就是___的经验。",a:"所谓",instr:"填空",instrEn:"Fill in the blank",body:"这就是___的经验。"},{q:"翻译：So-called success is not just money.",a:"所谓成功不只是钱。",instr:"翻译",instrEn:"Translate",body:"So-called success is not just money."},{q:"选择：“so-called method”用（所谓的 / 所有的）办法。",a:"所谓的",instr:"选择",instrEn:"Choose",body:"“so-called method”用（所谓的 / 所有的）办法。"}],note:"可中性解释概念，也可带怀疑/讽刺语气。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Can neutrally explain a term, or carry doubt/sarcasm.",typeEn:"Attributive / Formal"},{id:"5.14.2",name:"“则”表示对比或“那么就”",pinyin:"zé",type:"副词/连词（书面）",explainEn:"Use 则 to mark contrast (“whereas”) or a result (“then”) in formal Chinese.",structure:"A，而B则…；如果A，则B",examples:[{zh:"他喜欢安静，我则喜欢热闹。",en:"He likes quiet places, whereas I like lively ones."},{zh:"情况不同，方法则不同。",en:"If the situation is different, the method is different."},{zh:"努力则有可能成功。",en:"If you work hard, then success is possible."}],exercises:[{q:"填空：他坐地铁，我___开车。",a:"则",instr:"填空",instrEn:"Fill in the blank",body:"他坐地铁，我___开车。"},{q:"翻译：The situation is different, so the method is different.",a:"情况不同，方法则不同。",instr:"翻译",instrEn:"Translate",body:"The situation is different, so the method is different."},{q:"选择：书面“whereas”可用（则 / 要不）。",a:"则",instr:"选择",instrEn:"Choose",body:"书面“whereas”可用（则 / 要不）。"}],note:"常见书面结构：而……则……；如果……则……。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Common written patterns: 而…则…; 如果…则….",typeEn:"Adverb / Conj. (formal)"},{id:"5.14.3",name:"被动结构“为……所……”",pinyin:"wéi ... suǒ ...",type:"书面被动句",explainEn:"Use 为…所… as a formal passive structure: “be … by…”.",structure:"A + 为 + B + 所 + V",examples:[{zh:"他的故事为很多人所熟悉。",en:"His story is familiar to many people."},{zh:"这个地方为游客所喜爱。",en:"This place is loved by tourists."},{zh:"他的意见没有为大家所接受。",en:"His opinion was not accepted by everyone."}],exercises:[{q:"填空：这个地方___游客___喜爱。",a:"为；所",instr:"填空",instrEn:"Fill in the blank",body:"这个地方___游客___喜爱。"},{q:"翻译：His opinion was not accepted.",a:"他的意见没有为大家所接受。",instr:"翻译",instrEn:"Translate",body:"His opinion was not accepted."},{q:"把“大家接受了这个办法”改成“为……所……”被动。",a:"这个办法为大家所接受。"}],note:"较正式、书面，相当于“被”。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Formal/written, equivalent to 被.",typeEn:"Formal passive"},{id:"5.14.4",name:"“V起……”表示说到/提到某话题",pinyin:"V qǐ",type:"补语/固定结构",explainEn:"Use 说起/谈起/提起 + topic for “speaking of / when it comes to…”.",structure:"说起/谈起/提起 + N",examples:[{zh:"说起北京，我最喜欢秋天。",en:"Speaking of Beijing, I like autumn best."},{zh:"谈起工作，他有很多想法。",en:"When it comes to work, he has many ideas."},{zh:"提起这件事，他就笑了。",en:"When this matter is mentioned, he smiles."}],exercises:[{q:"填空：说___旅游，我很有兴趣。",a:"起",instr:"填空",instrEn:"Fill in the blank",body:"说___旅游，我很有兴趣。"},{q:"翻译：Speaking of work, he has many ideas.",a:"谈起工作，他有很多想法。",instr:"翻译",instrEn:"Translate",body:"Speaking of work, he has many ideas."},{q:"选择：“mention this matter”用（提起 / 提于）。",a:"提起",instr:"选择",instrEn:"Choose",body:"“mention this matter”用（提起 / 提于）。"}],note:"常见搭配：说起、谈起、提起。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Common pairings: 说起, 谈起, 提起.",typeEn:"Complement / Fixed"}]},{num:15,title:"纸上谈兵",points:[{id:"5.15.1",name:"可能补语“V得过 / V不过”",pinyin:"V deguò / V buguò",type:"可能补语",explainEn:"Use V得过/V不过 to say whether someone can overcome or beat something/someone.",structure:"V + 得过 / 不过 + 对象",examples:[{zh:"你一个人说得过他们吗？",en:"Can you win an argument against all of them alone?"},{zh:"我们跑不过他。",en:"We cannot run faster than him."},{zh:"这点困难我还应付得过。",en:"I can still handle this difficulty."}],exercises:[{q:"填空：我跑___他。",a:"不过",instr:"填空",instrEn:"Fill in the blank",body:"我跑___他。"},{q:"翻译：Can you beat them in an argument?",a:"你说得过他们吗？",instr:"翻译",instrEn:"Translate",body:"Can you beat them in an argument?"},{q:"选择：表示“can handle it”用（应付得过 / 应付起来）。",a:"应付得过",instr:"选择",instrEn:"Choose",body:"表示“can handle it”用（应付得过 / 应付起来）。"}],note:"常见“比不过、说不过、打不过、忙不过来”等。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Common: 比不过, 说不过, 打不过, 忙不过来.",typeEn:"Potential compl."},{id:"5.15.2",name:"副词“迟早”",pinyin:"chízǎo",type:"副词",explainEn:"Use 迟早 to mean “sooner or later”.",structure:"迟早 + 会/要 + V",examples:[{zh:"这个问题迟早要解决。",en:"This problem must be solved sooner or later."},{zh:"只要努力，迟早会成功。",en:"As long as you work hard, you will succeed sooner or later."},{zh:"他迟早会明白的。",en:"He will understand sooner or later."}],exercises:[{q:"填空：他___会知道。",a:"迟早",instr:"填空",instrEn:"Fill in the blank",body:"他___会知道。"},{q:"翻译：This problem must be solved sooner or later.",a:"这个问题迟早要解决。",instr:"翻译",instrEn:"Translate",body:"This problem must be solved sooner or later."},{q:"选择：“sooner or later”用（迟早 / 至今）。",a:"迟早",instr:"选择",instrEn:"Choose",body:"“sooner or later”用（迟早 / 至今）。"}],note:"表示早晚一定会发生。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Means it is bound to happen sooner or later.",typeEn:"Adverb"},{id:"5.15.3",name:"副词“再三”表示多次、反复",pinyin:"zàisān",type:"副词",explainEn:"Use 再三 to mean “repeatedly / again and again”.",structure:"再三 + V",examples:[{zh:"老师再三提醒我们要小心。",en:"The teacher repeatedly reminded us to be careful."},{zh:"我再三考虑后才决定。",en:"I decided only after thinking it over repeatedly."},{zh:"他再三向我道歉。",en:"He apologized to me repeatedly."}],exercises:[{q:"填空：老师___提醒大家。",a:"再三",instr:"填空",instrEn:"Fill in the blank",body:"老师___提醒大家。"},{q:"翻译：He apologized repeatedly.",a:"他再三道歉。",instr:"翻译",instrEn:"Translate",body:"He apologized repeatedly."},{q:"选择：多次认真考虑可说“再三（考虑 / 立刻）”。",a:"考虑",instr:"选择",instrEn:"Choose",body:"多次认真考虑可说“再三（考虑 / 立刻）”。"}],note:"较书面，通常修饰提醒、考虑、要求、说明等。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Rather formal; modifies remind/consider/require/explain.",typeEn:"Adverb"}]},{num:16,title:"体重与节食",points:[{id:"5.16.1",name:"“即”表示“就是/也就是”或“如果就”",pinyin:"jí",type:"书面副词/连词",explainEn:"Use 即 in formal Chinese for “namely / that is”, and sometimes “if…then…”.",structure:"A，即B；条件即结果",examples:[{zh:"春节，即农历新年。",en:"Spring Festival, that is, Lunar New Year."},{zh:"价格下降，即表示需求减少吗？",en:"Does a price drop mean demand decreased?"},{zh:"有问题即可联系我。",en:"If there is a problem, you can contact me."}],exercises:[{q:"填空：春节，___农历新年。",a:"即",instr:"填空",instrEn:"Fill in the blank",body:"春节，___农历新年。"},{q:"翻译：You can contact me if needed.",a:"有需要即可联系我。",instr:"翻译",instrEn:"Translate",body:"You can contact me if needed."},{q:"选择：书面“namely”可用（即 / 居然）。",a:"即",instr:"选择",instrEn:"Choose",body:"书面“namely”可用（即 / 居然）。"}],note:"“即”很书面，常见“即使、即将、即为、即可”。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"即 is very formal; e.g. 即使, 即将, 即为, 即可.",typeEn:"Formal adverb / conj."},{id:"5.16.2",name:"“个别”表示少数/单独",pinyin:"gèbié",type:"形容词/副词",explainEn:"Use 个别 to mean “individual / a few special cases”.",structure:"个别 + N；个别地 + V",examples:[{zh:"个别学生还没交作业。",en:"A few individual students have not handed in homework."},{zh:"这是个别现象，不代表全部。",en:"This is an individual case and does not represent all cases."},{zh:"老师会和学生个别谈话。",en:"The teacher will talk with students individually."}],exercises:[{q:"填空：___学生迟到了。",a:"个别",instr:"填空",instrEn:"Fill in the blank",body:"___学生迟到了。"},{q:"翻译：This is only an individual case.",a:"这只是个别现象。",instr:"翻译",instrEn:"Translate",body:"This is only an individual case."},{q:"选择：少数特殊情况用（个别 / 各自）。",a:"个别",instr:"选择",instrEn:"Choose",body:"少数特殊情况用（个别 / 各自）。"}],note:"强调不是大多数。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Stresses it is not the majority.",typeEn:"Adjective / Adverb"},{id:"5.16.3",name:"“非……才……”表示必须满足条件",pinyin:"fēi ... cái ...",type:"紧缩条件句",explainEn:"Use 非…才… to mean “only if… will…”, often with strong insistence.",structure:"非 + 条件 + 才 + 结果",examples:[{zh:"我非做完作业才睡觉。",en:"I won't sleep until I finish my homework."},{zh:"他非看到结果才放心。",en:"He won't feel at ease until he sees the result."},{zh:"这件事非你来才行。",en:"Only you can handle this matter."}],exercises:[{q:"填空：我___做完___休息。",a:"非；才",instr:"填空",instrEn:"Fill in the blank",body:"我___做完___休息。"},{q:"翻译：Only you can do this.",a:"这件事非你来才行。",instr:"翻译",instrEn:"Translate",body:"Only you can do this."},{q:"连接：看到结果。他才放心。（用“非……才……”）",a:"他非看到结果才放心。",instr:"连接",instrEn:"Join the sentences",body:"看到结果。他才放心。（用“非……才……”）"}],note:"语气较强；口语中也常见“非要……不可”。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Rather strong; speech often uses 非要…不可.",typeEn:"Contracted conditional"}]},{num:17,title:"在最美好的时刻离开",points:[{id:"5.17.1",name:"介词“以”表示用/按照/以……为",pinyin:"yǐ",type:"书面介词",explainEn:"Use 以 in formal Chinese for “with / by / according to / taking…as…”.",structure:"以 + N + V；以A为B",examples:[{zh:"我们以事实为根据。",en:"We take facts as our basis."},{zh:"请以邮件方式联系我。",en:"Please contact me by email."},{zh:"他以第一名的成绩毕业。",en:"He graduated with the top score."}],exercises:[{q:"填空：我们___事实为根据。",a:"以",instr:"填空",instrEn:"Fill in the blank",body:"我们___事实为根据。"},{q:"翻译：Please contact me by email.",a:"请以邮件方式联系我。",instr:"翻译",instrEn:"Translate",body:"Please contact me by email."},{q:"选择：“take health as the goal”可说“以健康（为 / 于）目标”。",a:"为",instr:"选择",instrEn:"Choose",body:"“take health as the goal”可说“以健康（为 / 于）目标”。"}],note:"较书面，常见“以……为……、以……方式”。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Rather formal; e.g. 以…为…, 以…方式.",typeEn:"Formal preposition"},{id:"5.17.2",name:"“平常”表示平时/普通",pinyin:"píngcháng",type:"名词/形容词",explainEn:"Use 平常 to mean “usually / ordinary”.",structure:"平常 + V；很平常",examples:[{zh:"我平常七点起床。",en:"I usually get up at seven."},{zh:"他今天和平常不一样。",en:"He is different from usual today."},{zh:"这是一件很平常的事。",en:"This is a very ordinary thing."}],exercises:[{q:"填空：我___坐地铁上班。",a:"平常",instr:"填空",instrEn:"Fill in the blank",body:"我___坐地铁上班。"},{q:"翻译：This is an ordinary thing.",a:"这是一件很平常的事。",instr:"翻译",instrEn:"Translate",body:"This is an ordinary thing."},{q:"选择：“usually”可用（平常 / 至今）。",a:"平常",instr:"选择",instrEn:"Choose",body:"“usually”可用（平常 / 至今）。"}],note:"可表示“平时”，也可表示“普通”。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:'Can mean "usually" or "ordinary".',typeEn:"Noun / Adjective"},{id:"5.17.3",name:"“宁可……也不/也要……”表示选择",pinyin:"nìngkě ... yě bù/yě yào ...",type:"选择复句",explainEn:"Use 宁可…也不/也要… to choose one option even if it is harder.",structure:"宁可 + A，也不/也要 + B",examples:[{zh:"我宁可走路，也不坐这么挤的车。",en:"I'd rather walk than take such a crowded bus."},{zh:"我宁可少睡一会儿，也要把工作做完。",en:"I'd rather sleep less and finish the work."},{zh:"他宁可自己吃亏，也不让朋友为难。",en:"He would rather suffer a loss himself than trouble his friend."}],exercises:[{q:"填空：我___走路，___不打车。",a:"宁可；也",instr:"填空",instrEn:"Fill in the blank",body:"我___走路，___不打车。"},{q:"翻译：I'd rather sleep less and finish the work.",a:"我宁可少睡一会儿，也要把工作做完。",instr:"翻译",instrEn:"Translate",body:"I'd rather sleep less and finish the work."},{q:"连接：自己吃亏。不让朋友为难。",a:"他宁可自己吃亏，也不让朋友为难。",instr:"连接",instrEn:"Join the sentences",body:"自己吃亏。不让朋友为难。"}],note:"用于两种选择中明确偏向一种。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Used to clearly favor one of two choices.",typeEn:"Alternative clause"}]},{num:18,title:"抽象艺术美不美",points:[{id:"5.18.1",name:"程度副词“极其”",pinyin:"jíqí",type:"副词",explainEn:"Use 极其 to mean “extremely”. It is formal.",structure:"极其 + Adj",examples:[{zh:"这个问题极其重要。",en:"This issue is extremely important."},{zh:"这里的环境极其安静。",en:"The environment here is extremely quiet."},{zh:"这种情况极其少见。",en:"This situation is extremely rare."}],exercises:[{q:"填空：这个问题___重要。",a:"极其",instr:"填空",instrEn:"Fill in the blank",body:"这个问题___重要。"},{q:"翻译：This situation is extremely rare.",a:"这种情况极其少见。",instr:"翻译",instrEn:"Translate",body:"This situation is extremely rare."},{q:"选择：较书面的“extremely”用（极其 / 挺）。",a:"极其",instr:"选择",instrEn:"Choose",body:"较书面的“extremely”用（极其 / 挺）。"}],note:"比“很、非常”更强且更书面。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Stronger and more formal than 很/非常.",typeEn:"Adverb"},{id:"5.18.2",name:"代词“其余”",pinyin:"qíyú",type:"代词/定语",explainEn:"Use 其余 to mean “the rest / remaining”.",structure:"其余 + N；其余的",examples:[{zh:"这两个留下，其余的都拿走。",en:"Keep these two; take away the rest."},{zh:"其余学生已经到了。",en:"The rest of the students have arrived."},{zh:"我只看了一部分，其余的以后再看。",en:"I only read part of it; I will read the rest later."}],exercises:[{q:"填空：这两个留下，___的拿走。",a:"其余",instr:"填空",instrEn:"Fill in the blank",body:"这两个留下，___的拿走。"},{q:"翻译：The rest of the students arrived.",a:"其余学生到了。",instr:"翻译",instrEn:"Translate",body:"The rest of the students arrived."},{q:"选择：“the remaining people”可说（其余的人 / 各自的人）。",a:"其余的人",instr:"选择",instrEn:"Choose",body:"“the remaining people”可说（其余的人 / 各自的人）。"}],note:"表示除已经提到的部分以外剩下的。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Means the rest, apart from what's already mentioned.",typeEn:"Pronoun / Attributive"},{id:"5.18.3",name:"“可见”表示由前文推出结论",pinyin:"kějiàn",type:"连接表达",explainEn:"Use 可见 to introduce a conclusion: “it can be seen that / therefore”.",structure:"事实。可见，+ 结论",examples:[{zh:"他每天都练习，可见他很认真。",en:"He practices every day, so we can see he is serious."},{zh:"大家都愿意来，可见这个活动很受欢迎。",en:"Everyone wants to come, showing the event is popular."},{zh:"销量一直增加，可见这个产品不错。",en:"Sales keep rising, so the product is clearly good."}],exercises:[{q:"填空：大家都来了，___这个活动很受欢迎。",a:"可见",instr:"填空",instrEn:"Fill in the blank",body:"大家都来了，___这个活动很受欢迎。"},{q:"翻译：It can be seen that he is serious.",a:"可见他很认真。",instr:"翻译",instrEn:"Translate",body:"It can be seen that he is serious."},{q:"选择：推出结论用（可见 / 以来）。",a:"可见",instr:"选择",instrEn:"Choose",body:"推出结论用（可见 / 以来）。"}],note:"前面给事实/证据，后面给判断。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"First give the facts/evidence, then the conclusion.",typeEn:"Connective expression"}]},{num:19,title:"家乡的萝卜饼",points:[{id:"5.19.1",name:"“N般（的）”表示像……一样",pinyin:"N bān (de)",type:"比喻/书面定语",explainEn:"Use 般 after a noun to mean “like / as…”. It is literary/formal.",structure:"N + 般（的）+ N/Adj",examples:[{zh:"孩子有阳光般的笑容。",en:"The child has a smile like sunshine."},{zh:"湖面像镜子般平静。",en:"The lake is calm like a mirror."},{zh:"他飞一般地跑了出去。",en:"He ran out as fast as if flying."}],exercises:[{q:"填空：她有阳光___的笑容。",a:"般",instr:"填空",instrEn:"Fill in the blank",body:"她有阳光___的笑容。"},{q:"翻译：The lake is as calm as a mirror.",a:"湖面像镜子般平静。",instr:"翻译",instrEn:"Translate",body:"The lake is as calm as a mirror."},{q:"选择：“like a dream”可说“梦（般 / 来）”。",a:"般",instr:"选择",instrEn:"Choose",body:"“like a dream”可说“梦（般 / 来）”。"}],note:"“般”较书面，常见“……般的、一般”。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"般 is rather formal; e.g. …般的, 一般.",typeEn:"Simile / Formal attr."},{id:"5.19.2",name:"动词“闻”表示听说/闻到",pinyin:"wén",type:"动词",explainEn:"Use 闻 to mean “smell” or, in formal expressions, “hear of”.",structure:"闻 + 气味；闻到；听闻",examples:[{zh:"我闻到饭香了。",en:"I can smell the food."},{zh:"这朵花闻起来很香。",en:"This flower smells nice."},{zh:"久闻你的名字。",en:"I have heard your name for a long time."}],exercises:[{q:"填空：我___到花香了。",a:"闻",instr:"填空",instrEn:"Fill in the blank",body:"我___到花香了。"},{q:"翻译：This flower smells nice.",a:"这朵花闻起来很香。",instr:"翻译",instrEn:"Translate",body:"This flower smells nice."},{q:"选择：“smell the food”可说（闻到 / 看到）饭香。",a:"闻到",instr:"选择",instrEn:"Choose",body:"“smell the food”可说（闻到 / 看到）饭香。"}],note:"现代口语最常见的是“闻到、闻起来”。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"In modern speech the most common are 闻到, 闻起来.",typeEn:"Verb"},{id:"5.19.3",name:"介词“趁”表示利用某个机会/时间",pinyin:"chèn",type:"介词",explainEn:"Use 趁 to mean “while / take advantage of a good time”.",structure:"趁 + 时间/机会 + V",examples:[{zh:"趁天气好，我们出去走走吧。",en:"While the weather is good, let's go out."},{zh:"趁年轻，多学点儿东西。",en:"While you are young, learn more."},{zh:"你趁热吃吧。",en:"Eat it while it is hot."}],exercises:[{q:"填空：___天气好，我们去爬山。",a:"趁",instr:"填空",instrEn:"Fill in the blank",body:"___天气好，我们去爬山。"},{q:"翻译：Eat it while it is hot.",a:"你趁热吃吧。",instr:"翻译",instrEn:"Translate",body:"Eat it while it is hot."},{q:"选择：“while young”用（趁年轻 / 至今年轻）。",a:"趁年轻",instr:"选择",instrEn:"Choose",body:"“while young”用（趁年轻 / 至今年轻）。"}],note:"“趁”后面一般是有利时机。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"趁 is followed by a favorable opportunity.",typeEn:"Preposition"}]},{num:20,title:"小人书摊",points:[{id:"5.20.1",name:"可能补语“V得起 / V不起”",pinyin:"V deqǐ / V buqǐ",type:"可能补语",explainEn:"Use V得起/V不起 to say someone can or cannot afford, bear, or deserve an action.",structure:"V + 得起 / 不起 + O",examples:[{zh:"这个房子太贵，我买不起。",en:"This house is too expensive; I cannot afford it."},{zh:"这么大的责任，我承担不起。",en:"I cannot bear such a big responsibility."},{zh:"这点费用我还付得起。",en:"I can still afford this cost."}],exercises:[{q:"填空：这台电脑太贵，我买___。",a:"不起",instr:"填空",instrEn:"Fill in the blank",body:"这台电脑太贵，我买___。"},{q:"翻译：I can afford this cost.",a:"这点费用我付得起。",instr:"翻译",instrEn:"Translate",body:"I can afford this cost."},{q:"选择：表示“cannot bear the responsibility”用（承担不起 / 承担不过）。",a:"承担不起",instr:"选择",instrEn:"Choose",body:"表示“cannot bear the responsibility”用（承担不起 / 承担不过）。"}],note:"常见：买不起、住不起、承担不起、看不起（另有“轻视”义）。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:'Common: 买不起, 住不起, 承担不起, 看不起 (also "look down on").',typeEn:"Potential compl."},{id:"5.20.2",name:"量词/动词“支”",pinyin:"zhī",type:"量词/动词",explainEn:"Use 支 as a measure word for pens, songs, teams, etc.; as a verb it can mean “support”.",structure:"一支 + 笔/歌/队伍；支 + V",examples:[{zh:"我买了一支笔。",en:"I bought a pen."},{zh:"她唱了一支歌。",en:"She sang a song."},{zh:"这支队伍很年轻。",en:"This team is very young."}],exercises:[{q:"填空：一___笔",a:"支",instr:"填空",instrEn:"Fill in the blank",body:"一___笔"},{q:"翻译：a song",a:"一支歌",instr:"翻译",instrEn:"Translate",body:"a song"},{q:"选择：笔的量词是（支 / 片）。",a:"支",instr:"选择",instrEn:"Choose",body:"笔的量词是（支 / 片）。"}],note:"HSK5量词语言点之一；“支”作动词还能表示支持、撑住。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"An HSK5 measure word; as a verb 支 can also mean support/prop up.",typeEn:"Measure word / Verb"},{id:"5.20.3",name:"介词“凭”表示凭借/根据",pinyin:"píng",type:"介词",explainEn:"Use 凭 to mean “by relying on / based on”.",structure:"凭 + 人/能力/证据 + V",examples:[{zh:"你凭什么这么说？",en:"What makes you say that?"},{zh:"他凭自己的努力取得了成功。",en:"He succeeded through his own effort."},{zh:"凭这张票可以进去。",en:"You can enter with this ticket."}],exercises:[{q:"填空：你___什么这么判断？",a:"凭",instr:"填空",instrEn:"Fill in the blank",body:"你___什么这么判断？"},{q:"翻译：You can enter with this ticket.",a:"凭这张票可以进去。",instr:"翻译",instrEn:"Translate",body:"You can enter with this ticket."},{q:"排序：努力 / 他 / 凭 / 成功了 / 自己的",a:"他凭自己的努力成功了。",instr:"排序",instrEn:"Reorder the words",body:"努力 / 他 / 凭 / 成功了 / 自己的"}],note:"常见：凭经验、凭证据、凭什么。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Common: 凭经验, 凭证据, 凭什么.",typeEn:"Preposition"}]},{num:21,title:"汉字叔叔：一个美国人的汉字情缘",points:[{id:"5.21.1",name:"副词“硬”表示强行/坚持要做",pinyin:"yìng",type:"副词",explainEn:"Use 硬 before a verb to mean “insist on / force oneself to / by force”.",structure:"硬 + V",examples:[{zh:"他身体不舒服，还硬要去上班。",en:"He feels unwell but still insists on going to work."},{zh:"不会就别硬装懂。",en:"If you don't know, don't pretend you do."},{zh:"我拉他回来，他硬是不听。",en:"I tried to pull him back, but he simply would not listen."}],exercises:[{q:"填空：他生病了还___要去。",a:"硬",instr:"填空",instrEn:"Fill in the blank",body:"他生病了还___要去。"},{q:"翻译：Don't pretend to understand.",a:"别硬装懂。",instr:"翻译",instrEn:"Translate",body:"Don't pretend to understand."},{q:"选择：表示“insist on going”用（硬要去 / 尽快去）。",a:"硬要去",instr:"选择",instrEn:"Choose",body:"表示“insist on going”用（硬要去 / 尽快去）。"}],note:"语气较强，常表示勉强、强行或固执。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Rather strong; often reluctant, forced or stubborn.",typeEn:"Adverb"},{id:"5.21.2",name:"“偶然”表示意外、不是经常",pinyin:"ǒurán",type:"形容词/副词",explainEn:"Use 偶然 to mean “by chance / accidental”.",structure:"偶然 + V；偶然的 + N",examples:[{zh:"我偶然在街上遇到了他。",en:"I met him on the street by chance."},{zh:"这是一次偶然的机会。",en:"This was an accidental opportunity."},{zh:"这个发现并不是偶然的。",en:"This discovery was not accidental."}],exercises:[{q:"填空：我___遇到了老同学。",a:"偶然",instr:"填空",instrEn:"Fill in the blank",body:"我___遇到了老同学。"},{q:"翻译：This was an accidental opportunity.",a:"这是一次偶然的机会。",instr:"翻译",instrEn:"Translate",body:"This was an accidental opportunity."},{q:"选择：“by chance”用（偶然 / 偶尔地每天）。",a:"偶然",instr:"选择",instrEn:"Choose",body:"“by chance”用（偶然 / 偶尔地每天）。"}],note:"“偶然”强调事情出乎计划；“偶尔”强调频率低。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:'偶然 stresses "by chance"; 偶尔 stresses low frequency.',typeEn:"Adjective / Adverb"},{id:"5.21.3",name:"副词“尽快”",pinyin:"jǐnkuài",type:"副词",explainEn:"Use 尽快 to mean “as soon as possible”.",structure:"尽快 + V",examples:[{zh:"请尽快回复我。",en:"Please reply as soon as possible."},{zh:"我们要尽快解决这个问题。",en:"We need to solve this problem as soon as possible."},{zh:"他会尽快赶回来。",en:"He will come back as soon as possible."}],exercises:[{q:"填空：请___联系我。",a:"尽快",instr:"填空",instrEn:"Fill in the blank",body:"请___联系我。"},{q:"翻译：We need to solve it as soon as possible.",a:"我们要尽快解决。",instr:"翻译",instrEn:"Translate",body:"We need to solve it as soon as possible."},{q:"选择：“as soon as possible”用（尽快 / 逐步）。",a:"尽快",instr:"选择",instrEn:"Choose",body:"“as soon as possible”用（尽快 / 逐步）。"}],note:"常用于请求、计划和正式沟通。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Used in requests, plans and formal communication.",typeEn:"Adverb"}]},{num:22,title:"阅读与思考",points:[{id:"5.22.1",name:"连词“一旦”",pinyin:"yídàn",type:"条件连词",explainEn:"Use 一旦 to mean “once / if something happens”.",structure:"一旦 + 情况，就/便 + 结果",examples:[{zh:"一旦决定了，就不要轻易改变。",en:"Once you decide, don't change it easily."},{zh:"一旦下雨，比赛就要停止。",en:"Once it rains, the game must stop."},{zh:"一旦发现问题，请马上告诉我。",en:"If you find a problem, tell me immediately."}],exercises:[{q:"填空：___决定了，就坚持下去。",a:"一旦",instr:"填空",instrEn:"Fill in the blank",body:"___决定了，就坚持下去。"},{q:"翻译：Once it rains, the game stops.",a:"一旦下雨，比赛就停止。",instr:"翻译",instrEn:"Translate",body:"Once it rains, the game stops."},{q:"连接：发现问题。马上告诉我。（用“一旦”）",a:"一旦发现问题，马上告诉我。",instr:"连接",instrEn:"Join the sentences",body:"发现问题。马上告诉我。（用“一旦”）"}],note:"强调某个条件一发生，后果就会出现。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Stresses that once a condition occurs, the consequence follows.",typeEn:"Conditional conj."},{id:"5.22.2",name:"副词“难免”",pinyin:"nánmiǎn",type:"副词/形容词",explainEn:"Use 难免 to mean “hard to avoid / inevitably”.",structure:"难免 + V/Adj",examples:[{zh:"第一次做，难免会出错。",en:"The first time you do it, mistakes are hard to avoid."},{zh:"工作太忙，难免有点儿累。",en:"With so much work, it is inevitable to feel tired."},{zh:"两个人一起生活，难免有不同意见。",en:"When two people live together, differences are inevitable."}],exercises:[{q:"填空：第一次做，___会出错。",a:"难免",instr:"填空",instrEn:"Fill in the blank",body:"第一次做，___会出错。"},{q:"翻译：Differences are inevitable.",a:"不同意见是难免的。",instr:"翻译",instrEn:"Translate",body:"Differences are inevitable."},{q:"选择：“inevitably”用（难免 / 干脆）。",a:"难免",instr:"选择",instrEn:"Choose",body:"“inevitably”用（难免 / 干脆）。"}],note:"通常表示不希望发生但很难完全避免。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Usually something unwanted but hard to fully avoid.",typeEn:"Adverb / Adjective"},{id:"5.22.3",name:"介词“自从”",pinyin:"zìcóng",type:"介词",explainEn:"Use 自从 to mark the starting point of a continuing time period: “since”.",structure:"自从 + 时间/事件 + 以来/以后，……",examples:[{zh:"自从来中国以后，他的汉语进步很快。",en:"Since coming to China, his Chinese has improved quickly."},{zh:"自从毕业以来，我们很少见面。",en:"Since graduation, we rarely meet."},{zh:"自从有了孩子，她更忙了。",en:"Since having a child, she has become busier."}],exercises:[{q:"填空：___毕业以后，我们没见过。",a:"自从",instr:"填空",instrEn:"Fill in the blank",body:"___毕业以后，我们没见过。"},{q:"翻译：Since coming to China, he improved.",a:"自从来中国以后，他进步了。",instr:"翻译",instrEn:"Translate",body:"Since coming to China, he improved."},{q:"排序：自从 / 他 / 工作以后 / 更忙了",a:"自从工作以后，他更忙了。",instr:"排序",instrEn:"Reorder the words",body:"自从 / 他 / 工作以后 / 更忙了"}],note:"“自从”后面是时间起点。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"自从 is followed by a starting point in time.",typeEn:"Preposition"}]},{num:23,title:"放手",points:[{id:"5.23.1",name:"“一致”表示相同/共同同意",pinyin:"yízhì",type:"形容词/副词",explainEn:"Use 一致 to mean “consistent / in agreement / unanimously”.",structure:"意见一致；一致 + V",examples:[{zh:"大家的意见一致。",en:"Everyone's opinions are consistent."},{zh:"我们一致同意这个办法。",en:"We unanimously agree with this method."},{zh:"他的说法和事实不一致。",en:"What he said is inconsistent with the facts."}],exercises:[{q:"填空：大家___同意。",a:"一致",instr:"填空",instrEn:"Fill in the blank",body:"大家___同意。"},{q:"翻译：Our opinions are consistent.",a:"我们的意见一致。",instr:"翻译",instrEn:"Translate",body:"Our opinions are consistent."},{q:"选择：“inconsistent with the facts”可说“和事实不（一致 / 各自）”。",a:"一致",instr:"选择",instrEn:"Choose",body:"“inconsistent with the facts”可说“和事实不（一致 / 各自）”。"}],note:"常见：意见一致、保持一致、一致认为。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Common: 意见一致, 保持一致, 一致认为.",typeEn:"Adjective / Adverb"},{id:"5.23.2",name:"代词“某”表示不确定的某人/某事",pinyin:"mǒu",type:"代词/定语",explainEn:"Use 某 before a noun to mean “a certain / some unspecified”.",structure:"某 + 人/地/时间；某某",examples:[{zh:"某一天，他突然来找我。",en:"One day, he suddenly came to see me."},{zh:"某位老师提出了这个问题。",en:"A certain teacher raised this question."},{zh:"张某已经离开了公司。",en:"A person surnamed Zhang has left the company."}],exercises:[{q:"填空：___一天，他突然回来了。",a:"某",instr:"填空",instrEn:"Fill in the blank",body:"___一天，他突然回来了。"},{q:"翻译：a certain teacher",a:"某位老师",instr:"翻译",instrEn:"Translate",body:"a certain teacher"},{q:"选择：“某个人”里的“某”表示（不确定 / 每一个）。",a:"不确定",instr:"选择",instrEn:"Choose",body:"“某个人”里的“某”表示（不确定 / 每一个）。"}],note:"常用于不知道、不方便说或不需要说具体是谁。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Used when the specific person is unknown, awkward or needless to name.",typeEn:"Pronoun / Attributive"},{id:"5.23.3",name:"副词“幸亏”",pinyin:"xìngkuī",type:"副词",explainEn:"Use 幸亏 to mean “fortunately / luckily”. It is followed by a clause, not just a noun.",structure:"幸亏 + 句子，不然/否则…",examples:[{zh:"幸亏你提醒我，不然我就忘了。",en:"Luckily you reminded me, otherwise I would have forgotten."},{zh:"幸亏我们出发得早，才没迟到。",en:"Luckily we left early, so we weren't late."},{zh:"幸亏雨停了，比赛才能继续。",en:"Luckily the rain stopped, so the game could continue."}],exercises:[{q:"填空：___你提醒我，我才没忘。",a:"幸亏",instr:"填空",instrEn:"Fill in the blank",body:"___你提醒我，我才没忘。"},{q:"翻译：Luckily we left early.",a:"幸亏我们出发得早。",instr:"翻译",instrEn:"Translate",body:"Luckily we left early."},{q:"补全：幸亏雨停了，___比赛能继续。",a:"所以/才",instr:"补全",instrEn:"Complete the sentence",body:"幸亏雨停了，___比赛能继续。"}],note:"和“多亏”相近，但“幸亏”后通常接小句。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Close to 多亏, but 幸亏 is usually followed by a clause.",typeEn:"Adverb"}]},{num:24,title:"支教行动",points:[{id:"5.24.1",name:"“行动”作名词/动词",pinyin:"xíngdòng",type:"动词/名词",explainEn:"Use 行动 to mean “action” or “take action / move”.",structure:"采取行动；立即行动",examples:[{zh:"我们应该马上行动。",en:"We should act immediately."},{zh:"计划已经有了，现在需要行动。",en:"We have a plan; now we need action."},{zh:"保护环境需要大家共同的行动。",en:"Protecting the environment needs everyone’s action."}],exercises:[{q:"填空：我们应该马上___。",a:"行动",instr:"填空",instrEn:"Fill in the blank",body:"我们应该马上___。"},{q:"翻译：Now we need action.",a:"现在需要行动。",instr:"翻译",instrEn:"Translate",body:"Now we need action."},{q:"选择：“take action”可说（采取行动 / 进行义务）。",a:"采取行动",instr:"选择",instrEn:"Choose",body:"“take action”可说（采取行动 / 进行义务）。"}],note:"常见搭配：采取行动、立即行动、实际行动。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Common: 采取行动, 立即行动, 实际行动.",typeEn:"Verb / Noun"},{id:"5.24.2",name:"“义务”表示责任/义务性的",pinyin:"yìwù",type:"名词/定语",explainEn:"Use 义务 to mean “duty / obligation”; before a noun it can mean “voluntary/compulsory public service”.",structure:"有义务 + V；义务 + N",examples:[{zh:"父母有照顾孩子的义务。",en:"Parents have a duty to care for children."},{zh:"每个人都有保护环境的义务。",en:"Everyone has a duty to protect the environment."},{zh:"我们周末参加了义务劳动。",en:"We took part in voluntary public-service work on the weekend."}],exercises:[{q:"填空：每个人都有保护环境的___。",a:"义务",instr:"填空",instrEn:"Fill in the blank",body:"每个人都有保护环境的___。"},{q:"翻译：Parents have a duty to care for children.",a:"父母有照顾孩子的义务。",instr:"翻译",instrEn:"Translate",body:"Parents have a duty to care for children."},{q:"选择：常见搭配是（义务劳动 / 义务天气）。",a:"义务劳动",instr:"选择",instrEn:"Choose",body:"常见搭配是（义务劳动 / 义务天气）。"}],note:"“义务”可作名词，也可修饰“劳动、教育”等。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"义务 can be a noun or modify 劳动/教育.",typeEn:"Noun / Attributive"}]},{num:25,title:"给自己加满水",points:[{id:"5.25.1",name:"介词“朝”表示方向/面对",pinyin:"cháo",type:"介词/动词",explainEn:"Use 朝 to mean “toward / facing”.",structure:"朝 + 方向/人 + V；坐…朝…",examples:[{zh:"他朝我笑了笑。",en:"He smiled at me."},{zh:"请朝前走。",en:"Please walk forward."},{zh:"这个房间朝南。",en:"This room faces south."}],exercises:[{q:"填空：他___我走来。",a:"朝",instr:"填空",instrEn:"Fill in the blank",body:"他___我走来。"},{q:"翻译：This room faces south.",a:"这个房间朝南。",instr:"翻译",instrEn:"Translate",body:"This room faces south."},{q:"选择：“walk toward the door”可说“朝门（走 / 来）”。",a:"走",instr:"选择",instrEn:"Choose",body:"“walk toward the door”可说“朝门（走 / 来）”。"}],note:"和“往”接近；“朝”还可表示建筑物朝向。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Close to 往; 朝 can also mean which way a building faces.",typeEn:"Preposition / Verb"},{id:"5.25.2",name:"副词“简直”表示强烈强调",pinyin:"jiǎnzhí",type:"副词",explainEn:"Use 简直 to strongly emphasize: “simply / practically / really”.",structure:"简直 + 是/Adj/V",examples:[{zh:"这里简直太美了。",en:"This place is simply beautiful."},{zh:"他忙得简直没时间吃饭。",en:"He is so busy he practically has no time to eat."},{zh:"这简直是不可能的。",en:"This is simply impossible."}],exercises:[{q:"填空：这里___太漂亮了。",a:"简直",instr:"填空",instrEn:"Fill in the blank",body:"这里___太漂亮了。"},{q:"翻译：This is simply impossible.",a:"这简直是不可能的。",instr:"翻译",instrEn:"Translate",body:"This is simply impossible."},{q:"选择：强烈强调用（简直 / 偶然）。",a:"简直",instr:"选择",instrEn:"Choose",body:"强烈强调用（简直 / 偶然）。"}],note:"带强烈感情色彩，常用于夸张或惊讶。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Strongly emotive; used for exaggeration or surprise.",typeEn:"Adverb"}]},{num:26,title:"你属于哪一种“忙”",points:[{id:"5.26.1",name:"“来”表示大约数量；“一来……二来……”列理由",pinyin:"lái / yīlái ... èrlái ...",type:"数量/列举结构",explainEn:"来 after a number can mean “about/over”. 一来…二来… lists two reasons.",structure:"数量 + 来 + 量词/Adj；一来…二来…",examples:[{zh:"这条鱼有五斤来重。",en:"This fish weighs a little over five jin."},{zh:"我不买，一来太贵，二来我也不需要。",en:"I won't buy it: first, it's too expensive; second, I don't need it."},{zh:"他有三十来岁。",en:"He is around thirty years old."}],exercises:[{q:"填空：他有三十___岁。",a:"来",instr:"填空",instrEn:"Fill in the blank",body:"他有三十___岁。"},{q:"翻译：First it's expensive; second, I don't need it.",a:"一来太贵，二来我不需要。",instr:"翻译",instrEn:"Translate",body:"First it's expensive; second, I don't need it."},{q:"用“一来……二来……”说两个不去的理由。",a:"一来我很忙，二来天气不好。"}],note:"“来”表示约数时放在数词后；“一来二来”用于列两个理由。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"来 for an approximate number goes after the number; 一来…二来… lists two reasons.",typeEn:"Quantity / Enumeration"},{id:"5.26.2",name:"“至于”表示转到另一话题/达到某程度",pinyin:"zhìyú",type:"介词/动词",explainEn:"Use 至于 for “as for…”; 不至于 means “not to the extent of…”.",structure:"至于 + 话题；不至于 + V/Adj",examples:[{zh:"我们决定去，至于时间以后再定。",en:"We decided to go; as for the time, we'll decide later."},{zh:"至于费用，我还要问一下。",en:"As for the cost, I still need to ask."},{zh:"他只是迟到，不至于被开除。",en:"He was only late; it shouldn't go as far as being fired."}],exercises:[{q:"填空：___具体时间，我们再商量。",a:"至于",instr:"填空",instrEn:"Fill in the blank",body:"___具体时间，我们再商量。"},{q:"翻译：As for the cost, I'll ask.",a:"至于费用，我再问。",instr:"翻译",instrEn:"Translate",body:"As for the cost, I'll ask."},{q:"选择：“not to the extent of”用（不至于 / 不以来）。",a:"不至于",instr:"选择",instrEn:"Choose",body:"“not to the extent of”用（不至于 / 不以来）。"}],note:"常用于话题转换；“不至于”表示程度没有那么严重。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:'Used to switch topics; 不至于 means "not to that extent".',typeEn:"Preposition / Verb"},{id:"5.26.3",name:"副词“总算”",pinyin:"zǒngsuàn",type:"副词",explainEn:"Use 总算 to mean “finally / at last”, often after difficulty or waiting.",structure:"总算 + V/Adj",examples:[{zh:"我们总算到家了。",en:"We finally got home."},{zh:"这个问题总算解决了。",en:"This problem is finally solved."},{zh:"等了一个小时，他总算来了。",en:"After waiting an hour, he finally came."}],exercises:[{q:"填空：问题___解决了。",a:"总算",instr:"填空",instrEn:"Fill in the blank",body:"问题___解决了。"},{q:"翻译：We finally arrived.",a:"我们总算到了。",instr:"翻译",instrEn:"Translate",body:"We finally arrived."},{q:"选择：经历困难后“finally”用（总算 / 偶然）。",a:"总算",instr:"选择",instrEn:"Choose",body:"经历困难后“finally”用（总算 / 偶然）。"}],note:"和“终于”接近；“总算”常带松一口气的感觉。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Close to 终于; 总算 carries a sense of relief.",typeEn:"Adverb"}]},{num:27,title:"下棋",points:[{id:"5.27.1",name:"“V下来”表示固定、保存、持续到现在",pinyin:"V xiàlái",type:"趋向补语引申",explainEn:"Use V下来 to show something becomes fixed, is recorded/saved, or continues and remains.",structure:"V + 下来",examples:[{zh:"日期已经定下来了。",en:"The date has been fixed."},{zh:"请把这个号码记下来。",en:"Please write down this number."},{zh:"这个习惯一直保持下来了。",en:"This habit has continued."}],exercises:[{q:"填空：日期已经定___了。",a:"下来",instr:"填空",instrEn:"Fill in the blank",body:"日期已经定___了。"},{q:"翻译：Please write down the number.",a:"请把号码记下来。",instr:"翻译",instrEn:"Translate",body:"Please write down the number."},{q:"选择：“record it”可说“记（下来 / 出来）”。",a:"下来",instr:"选择",instrEn:"Choose",body:"“record it”可说“记（下来 / 出来）”。"}],note:"常见：定下来、记下来、保存下来、坚持下来。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Common: 定下来, 记下来, 保存下来, 坚持下来.",typeEn:"Directional (fig.)"},{id:"5.27.2",name:"“舍得 / 舍不得”表示愿不愿放弃",pinyin:"shěde / shěbude",type:"可能补语式固定词",explainEn:"Use 舍得/舍不得 to mean “be willing / reluctant to give up, spend, or leave”.",structure:"舍得/舍不得 + V/O",examples:[{zh:"我舍不得离开这里。",en:"I am reluctant to leave here."},{zh:"你舍得把这本书送人吗？",en:"Are you willing to give this book away?"},{zh:"他舍不得花钱买贵东西。",en:"He is reluctant to spend money on expensive things."}],exercises:[{q:"填空：我___离开家。",a:"舍不得",instr:"填空",instrEn:"Fill in the blank",body:"我___离开家。"},{q:"翻译：Are you willing to give it away?",a:"你舍得送人吗？",instr:"翻译",instrEn:"Translate",body:"Are you willing to give it away?"},{q:"选择：不愿意花钱用（舍不得 / 来不及）。",a:"舍不得",instr:"选择",instrEn:"Choose",body:"不愿意花钱用（舍不得 / 来不及）。"}],note:"“舍”这里有放弃、割舍的意思。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Here 舍 means to give up / part with.",typeEn:"Potential-compl. idiom"}]},{num:28,title:"最受欢迎的毕业生",points:[{id:"5.28.1",name:"副词“从此”",pinyin:"cóngcǐ",type:"时间副词",explainEn:"Use 从此 to mean “from then on”.",structure:"从此 + 句子",examples:[{zh:"从此以后，他每天早起。",en:"From then on, he got up early every day."},{zh:"那次以后，我们从此成了朋友。",en:"After that, we became friends from then on."},{zh:"他离开后，从此没有回来。",en:"After he left, he never came back."}],exercises:[{q:"填空：___以后，他改变了习惯。",a:"从此",instr:"填空",instrEn:"Fill in the blank",body:"___以后，他改变了习惯。"},{q:"翻译：From then on, we became friends.",a:"从此我们成了朋友。",instr:"翻译",instrEn:"Translate",body:"From then on, we became friends."},{q:"选择：“from then on”用（从此 / 自从）。",a:"从此",instr:"选择",instrEn:"Choose",body:"“from then on”用（从此 / 自从）。"}],note:"“自从”后需接起点；“从此”本身就是“从那个时候起”。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:'自从 needs a starting point; 从此 already means "from then on".',typeEn:"Time adverb"},{id:"5.28.2",name:"“假设”表示假定",pinyin:"jiǎshè",type:"动词/名词",explainEn:"Use 假设 to mean “suppose / assumption”.",structure:"假设 + 句子；一个假设",examples:[{zh:"假设明天下雨，我们怎么办？",en:"Suppose it rains tomorrow; what will we do?"},{zh:"这个结论建立在一个假设上。",en:"This conclusion is based on an assumption."},{zh:"假设你有一个月假期，你想去哪儿？",en:"Suppose you had a month off; where would you go?"}],exercises:[{q:"填空：___明天下雨，我们就改时间。",a:"假设",instr:"填空",instrEn:"Fill in the blank",body:"___明天下雨，我们就改时间。"},{q:"翻译：This is only an assumption.",a:"这只是一个假设。",instr:"翻译",instrEn:"Translate",body:"This is only an assumption."},{q:"选择：名词“assumption”可说（假设 / 假如地）。",a:"假设",instr:"选择",instrEn:"Choose",body:"名词“assumption”可说（假设 / 假如地）。"}],note:"既可作动词引出假设条件，也可作名词。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Can be a verb introducing a hypothesis, or a noun.",typeEn:"Verb / Noun"},{id:"5.28.3",name:"“堆”作名词/动词",pinyin:"duī",type:"动词/名词/量词性名词",explainEn:"Use 堆 for “pile / heap” or “pile up”.",structure:"一堆 + N；把N堆在…",examples:[{zh:"桌上有一堆书。",en:"There is a pile of books on the table."},{zh:"别把衣服都堆在床上。",en:"Don't pile all the clothes on the bed."},{zh:"门口堆着很多箱子。",en:"Many boxes are piled at the door."}],exercises:[{q:"填空：桌上有一___书。",a:"堆",instr:"填空",instrEn:"Fill in the blank",body:"桌上有一___书。"},{q:"翻译：Don't pile the clothes here.",a:"别把衣服堆在这里。",instr:"翻译",instrEn:"Translate",body:"Don't pile the clothes here."},{q:"选择：表示“一堆东西”用（一堆 / 一支）。",a:"一堆",instr:"选择",instrEn:"Choose",body:"表示“一堆东西”用（一堆 / 一支）。"}],note:"可表示数量“一堆”，也可作动词“堆起来”。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:'Can mean the quantity "a pile", or the verb "to pile up".',typeEn:"Verb / Noun / M.w."}]},{num:29,title:"培养对手",points:[{id:"5.29.1",name:"“不如 / 与其……不如……”表示比较选择",pinyin:"bùrú / yǔqí ... bùrú ...",type:"比较/选择复句",explainEn:"Use 不如 for “not as good as”; 与其…不如… means “rather than…, better to…”.",structure:"A 不如 B；与其 + A，不如 + B",examples:[{zh:"这家饭店不如那家安静。",en:"This restaurant is not as quiet as that one."},{zh:"与其在家等，不如出去看看。",en:"Rather than wait at home, it's better to go out."},{zh:"坐车不如走路方便。",en:"Taking a car is not as convenient as walking."}],exercises:[{q:"填空：与其等，不___现在去。",a:"如",instr:"填空",instrEn:"Fill in the blank",body:"与其等，不___现在去。"},{q:"翻译：This one is not as good as that one.",a:"这个不如那个好。",instr:"翻译",instrEn:"Translate",body:"This one is not as good as that one."},{q:"连接：在家看电视。出去运动更好。",a:"与其在家看电视，不如出去运动。",instr:"连接",instrEn:"Join the sentences",body:"在家看电视。出去运动更好。"}],note:"“与其”后是较不想选的做法，“不如”后是更好的选择。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"与其 introduces the less-preferred option; 不如 the better one.",typeEn:"Comparison / Alternative"},{id:"5.29.2",name:"副词/形容词“干脆”",pinyin:"gāncuì",type:"副词/形容词",explainEn:"Use 干脆 to mean “simply / just”; as an adjective, “decisive / straightforward”.",structure:"干脆 + V；答应得很干脆",examples:[{zh:"太晚了，我们干脆明天再去。",en:"It's too late; let's simply go tomorrow."},{zh:"他干脆把问题说清楚了。",en:"He simply explained the issue clearly."},{zh:"他答应得很干脆。",en:"He agreed very readily."}],exercises:[{q:"填空：太麻烦了，___不去了。",a:"干脆",instr:"填空",instrEn:"Fill in the blank",body:"太麻烦了，___不去了。"},{q:"翻译：He agreed very readily.",a:"他答应得很干脆。",instr:"翻译",instrEn:"Translate",body:"He agreed very readily."},{q:"选择：“simply do it tomorrow”用（干脆明天做 / 逐步明天做）。",a:"干脆明天做",instr:"选择",instrEn:"Choose",body:"“simply do it tomorrow”用（干脆明天做 / 逐步明天做）。"}],note:"表示决定直接、不绕弯。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Means deciding directly, without beating around the bush.",typeEn:"Adverb / Adjective"},{id:"5.29.3",name:"“万一”表示小概率的不好情况",pinyin:"wànyī",type:"条件副词/名词",explainEn:"Use 万一 for an unlikely possible problem: “in case / what if”.",structure:"万一 + 不好情况，…",examples:[{zh:"万一下雨，我们就改时间。",en:"If it happens to rain, we'll change the time."},{zh:"带把伞吧，万一需要呢。",en:"Take an umbrella, just in case."},{zh:"万一出了问题，马上联系我。",en:"If something goes wrong, contact me immediately."}],exercises:[{q:"填空：___下雨怎么办？",a:"万一",instr:"填空",instrEn:"Fill in the blank",body:"___下雨怎么办？"},{q:"翻译：Take it, just in case.",a:"带着吧，以防万一。",instr:"翻译",instrEn:"Translate",body:"Take it, just in case."},{q:"选择：小概率风险用（万一 / 从此）。",a:"万一",instr:"选择",instrEn:"Choose",body:"小概率风险用（万一 / 从此）。"}],note:"常说“以防万一、不怕一万，就怕万一”。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Common: 以防万一; 不怕一万，就怕万一.",typeEn:"Conditional adv. / Noun"}]},{num:30,title:"竞争让市场更高效",points:[{id:"5.30.1",name:"“无意 / 无意中”",pinyin:"wúyì / wúyìzhōng",type:"副词/动词",explainEn:"Use 无意 to mean “have no intention”; 无意中 means “accidentally”.",structure:"无意 + V；无意中 + V",examples:[{zh:"我无意伤害你。",en:"I had no intention to hurt you."},{zh:"我无意中听到了这个消息。",en:"I heard the news by accident."},{zh:"他只是无意中说错了。",en:"He only said it wrong accidentally."}],exercises:[{q:"填空：我___中发现了这张照片。",a:"无意",instr:"填空",instrEn:"Fill in the blank",body:"我___中发现了这张照片。"},{q:"翻译：I had no intention to hurt you.",a:"我无意伤害你。",instr:"翻译",instrEn:"Translate",body:"I had no intention to hurt you."},{q:"选择：“accidentally”用（无意中 / 至今）。",a:"无意中",instr:"选择",instrEn:"Choose",body:"“accidentally”用（无意中 / 至今）。"}],note:"注意“无意做”与“无意中做”的区别。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Note the difference between 无意做 and 无意中做.",typeEn:"Adverb / Verb"},{id:"5.30.2",name:"“有利（于）”表示有好处",pinyin:"yǒulì (yú)",type:"形容词",explainEn:"Use 有利于 to mean “be beneficial to / help”.",structure:"A + 有利于 + B/V",examples:[{zh:"运动有利于健康。",en:"Exercise is good for health."},{zh:"这个政策有利于年轻人找工作。",en:"This policy helps young people find jobs."},{zh:"多交流有利于解决问题。",en:"More communication helps solve problems."}],exercises:[{q:"填空：运动___健康。",a:"有利于",instr:"填空",instrEn:"Fill in the blank",body:"运动___健康。"},{q:"翻译：This helps solve the problem.",a:"这有利于解决问题。",instr:"翻译",instrEn:"Translate",body:"This helps solve the problem."},{q:"选择：固定搭配是“有利（于 / 为）”。",a:"于",instr:"选择",instrEn:"Choose",body:"固定搭配是“有利（于 / 为）”。"}],note:"反义词是“不利于”。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Its antonym is 不利于.",typeEn:"Adjective"},{id:"5.30.3",name:"副词“的确”",pinyin:"díquè",type:"副词",explainEn:"Use 的确 to confirm something is true: “indeed / really”.",structure:"的确 + 谓语",examples:[{zh:"这个问题的确很难。",en:"This problem is indeed difficult."},{zh:"他的确进步了很多。",en:"He really has improved a lot."},{zh:"这里的风景的确很美。",en:"The scenery here really is beautiful."}],exercises:[{q:"填空：这件事___很重要。",a:"的确",instr:"填空",instrEn:"Fill in the blank",body:"这件事___很重要。"},{q:"翻译：He really improved.",a:"他的确进步了。",instr:"翻译",instrEn:"Translate",body:"He really improved."},{q:"选择：确认事实用（的确 / 万一）。",a:"的确",instr:"选择",instrEn:"Choose",body:"确认事实用（的确 / 万一）。"}],note:"与“确实”接近。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Close to 确实.",typeEn:"Adverb"}]},{num:31,title:"登门槛效应",points:[{id:"5.31.1",name:"语气词“嗯”",pinyin:"èn / ńg",type:"语气词",explainEn:"Use 嗯 to show agreement, thinking, surprise, or a response, depending on tone.",structure:"嗯，+ 回答 / 嗯？",examples:[{zh:"A：你明天来吗？B：嗯，来。",en:"A: Will you come tomorrow? B: Yes."},{zh:"嗯，我想想。",en:"Hmm, let me think."},{zh:"嗯？你刚才说什么？",en:"Huh? What did you just say?"}],exercises:[{q:"选择：表示同意可说（嗯 / 勿）。",a:"嗯",instr:"选择",instrEn:"Choose",body:"表示同意可说（嗯 / 勿）。"},{q:"翻译：Hmm, let me think.",a:"嗯，我想想。",instr:"翻译",instrEn:"Translate",body:"Hmm, let me think."},{q:"补全：A：你知道吗？B：___，知道。",a:"嗯",instr:"补全",instrEn:"Complete the sentence",body:"A：你知道吗？B：___，知道。"}],note:"不同语调表达不同态度，是口语交际语言点。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Different intonations show different attitudes; a spoken-interaction point.",typeEn:"Modal particle"},{id:"5.31.2",name:"“轻易”表示容易地/随便地",pinyin:"qīngyì",type:"副词",explainEn:"Use 轻易 to mean “easily / casually”, often in negative sentences.",structure:"轻易 + V；不轻易 + V",examples:[{zh:"不要轻易放弃。",en:"Don't give up easily."},{zh:"他不轻易相信别人。",en:"He does not easily trust others."},{zh:"这个决定不能轻易改变。",en:"This decision should not be changed casually."}],exercises:[{q:"填空：不要___放弃。",a:"轻易",instr:"填空",instrEn:"Fill in the blank",body:"不要___放弃。"},{q:"翻译：He does not easily trust others.",a:"他不轻易相信别人。",instr:"翻译",instrEn:"Translate",body:"He does not easily trust others."},{q:"选择：常与否定搭配的是（轻易 / 立刻）。",a:"轻易",instr:"选择",instrEn:"Choose",body:"常与否定搭配的是（轻易 / 立刻）。"}],note:"“容易”多描述事情难不难；“轻易”多修饰人的动作。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"容易 describes how hard a thing is; 轻易 modifies a person's action.",typeEn:"Adverb"}]},{num:32,title:"身边的环保",points:[{id:"5.32.1",name:"“密切”表示关系近/使关系更紧密",pinyin:"mìqiè",type:"形容词/动词",explainEn:"Use 密切 to mean “close” in relationship, or “strengthen” a relationship.",structure:"关系密切；密切 + 联系",examples:[{zh:"我们和客户的关系很密切。",en:"Our relationship with customers is close."},{zh:"这件事和健康密切相关。",en:"This matter is closely related to health."},{zh:"新的交通方式密切了两地的联系。",en:"The new transportation strengthened the connection between the two places."}],exercises:[{q:"填空：两者关系很___。",a:"密切",instr:"填空",instrEn:"Fill in the blank",body:"两者关系很___。"},{q:"翻译：It is closely related to health.",a:"它和健康密切相关。",instr:"翻译",instrEn:"Translate",body:"It is closely related to health."},{q:"选择：固定搭配“密切（相关 / 到达）”。",a:"相关",instr:"选择",instrEn:"Choose",body:"固定搭配“密切（相关 / 到达）”。"}],note:"常见：关系密切、密切联系、密切相关。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Common: 关系密切, 密切联系, 密切相关.",typeEn:"Adjective / Verb"},{id:"5.32.2",name:"副词“尽量”",pinyin:"jǐnliàng",type:"副词",explainEn:"Use 尽量 to mean “as much/as far as possible”.",structure:"尽量 + V/Adj",examples:[{zh:"请尽量早点儿来。",en:"Please come as early as possible."},{zh:"我们尽量少用塑料袋。",en:"We try to use as few plastic bags as possible."},{zh:"你尽量多休息。",en:"Try to rest as much as possible."}],exercises:[{q:"填空：请___早点儿到。",a:"尽量",instr:"填空",instrEn:"Fill in the blank",body:"请___早点儿到。"},{q:"翻译：Try to rest as much as possible.",a:"你尽量多休息。",instr:"翻译",instrEn:"Translate",body:"Try to rest as much as possible."},{q:"选择：“as much as possible”用（尽量 / 偶然）。",a:"尽量",instr:"选择",instrEn:"Choose",body:"“as much as possible”用（尽量 / 偶然）。"}],note:"读 jǐnliàng。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Read jǐnliàng.",typeEn:"Adverb"},{id:"5.32.3",name:"副词“逐步”",pinyin:"zhúbù",type:"副词",explainEn:"Use 逐步 to mean “step by step / gradually in stages”.",structure:"逐步 + V",examples:[{zh:"我们要逐步改善这个问题。",en:"We need to improve this problem step by step."},{zh:"公司正在逐步扩大市场。",en:"The company is gradually expanding its market."},{zh:"他的身体逐步恢复了。",en:"His health gradually recovered."}],exercises:[{q:"填空：计划正在___进行。",a:"逐步",instr:"填空",instrEn:"Fill in the blank",body:"计划正在___进行。"},{q:"翻译：The company is expanding step by step.",a:"公司正在逐步扩大。",instr:"翻译",instrEn:"Translate",body:"The company is expanding step by step."},{q:"选择：“step by step”用（逐步 / 立刻）。",a:"逐步",instr:"选择",instrEn:"Choose",body:"“step by step”用（逐步 / 立刻）。"}],note:"比“逐渐”更强调有步骤、分阶段。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"More than 逐渐, it stresses steps/stages.",typeEn:"Adverb"}]},{num:33,title:"以堵治堵——缓解交通有妙招",points:[{id:"5.33.1",name:"副词“照常”",pinyin:"zhàocháng",type:"副词/形容词",explainEn:"Use 照常 to mean “as usual”.",structure:"照常 + V；一切照常",examples:[{zh:"虽然下雨，比赛照常进行。",en:"Although it rained, the game went on as usual."},{zh:"明天照常上课。",en:"Classes will continue as usual tomorrow."},{zh:"他生病了，工作却一切照常。",en:"He was sick, but work continued as usual."}],exercises:[{q:"填空：明天___上班。",a:"照常",instr:"填空",instrEn:"Fill in the blank",body:"明天___上班。"},{q:"翻译：The game continued as usual.",a:"比赛照常进行。",instr:"翻译",instrEn:"Translate",body:"The game continued as usual."},{q:"选择：“as usual”用（照常 / 从此）。",a:"照常",instr:"选择",instrEn:"Choose",body:"“as usual”用（照常 / 从此）。"}],note:"表示没有因为特殊情况而改变。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Means unchanged despite special circumstances.",typeEn:"Adverb / Adjective"},{id:"5.33.2",name:"“难怪 / 怪不得”表示“原来如此”",pinyin:"nánguài / guàibude",type:"副词",explainEn:"Use 难怪/怪不得 for “no wonder”.",structure:"难怪/怪不得 + 结果；原因，难怪…",examples:[{zh:"你昨晚没睡好，难怪这么累。",en:"You didn't sleep well; no wonder you're so tired."},{zh:"原来他在国外住过，怪不得英语这么好。",en:"He lived abroad; no wonder his English is so good."},{zh:"外面下雪了，难怪这么冷。",en:"It snowed outside; no wonder it's so cold."}],exercises:[{q:"填空：你没吃饭，___这么饿。",a:"难怪",instr:"填空",instrEn:"Fill in the blank",body:"你没吃饭，___这么饿。"},{q:"翻译：No wonder his English is so good.",a:"难怪他的英语这么好。",instr:"翻译",instrEn:"Translate",body:"No wonder his English is so good."},{q:"选择：“no wonder”用（难怪 / 万一）。",a:"难怪",instr:"选择",instrEn:"Choose",body:"“no wonder”用（难怪 / 万一）。"}],note:"常在知道原因后表达“原来如此”。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:`Expresses "so that's why" once the reason is known.`,typeEn:"Adverb"},{id:"5.33.3",name:"“与其……（倒）不如/宁可……”表示选择",pinyin:"yǔqí ... (dào) bùrú / nìngkě ...",type:"选择复句",explainEn:"Use 与其…不如/宁可… to say “rather than A, better/prefer B”.",structure:"与其 + A，不如/宁可 + B",examples:[{zh:"与其等别人，不如自己做。",en:"Rather than wait for others, it's better to do it yourself."},{zh:"与其开车堵在路上，倒不如坐地铁。",en:"Rather than be stuck driving, it is better to take the subway."},{zh:"与其后悔，我宁可现在试一试。",en:"Rather than regret it, I'd rather try now."}],exercises:[{q:"填空：___在家等，___出去看看。",a:"与其；不如",instr:"填空",instrEn:"Fill in the blank",body:"___在家等，___出去看看。"},{q:"翻译：Rather than wait, do it yourself.",a:"与其等，不如自己做。",instr:"翻译",instrEn:"Translate",body:"Rather than wait, do it yourself."},{q:"连接：开车很堵。坐地铁更好。",a:"与其开车，不如坐地铁。",instr:"连接",instrEn:"Join the sentences",body:"开车很堵。坐地铁更好。"}],note:"“与其”提出放弃的选择，后面给更愿意选择的方案。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"与其 gives the rejected option, then the preferred one.",typeEn:"Alternative clause"}]},{num:34,title:"鸟儿的护肤术",points:[{id:"5.34.1",name:"连词“总之”",pinyin:"zǒngzhī",type:"连词",explainEn:"Use 总之 to summarize: “in short / all in all”.",structure:"前文。总之，+ 总结",examples:[{zh:"总之，我们要先解决最重要的问题。",en:"In short, we need to solve the most important problem first."},{zh:"方法很多，总之适合自己最重要。",en:"There are many methods; in short, what suits you matters most."},{zh:"总之，这次旅行很顺利。",en:"All in all, the trip went smoothly."}],exercises:[{q:"填空：___，我们决定继续。",a:"总之",instr:"填空",instrEn:"Fill in the blank",body:"___，我们决定继续。"},{q:"翻译：In short, the trip went smoothly.",a:"总之，这次旅行很顺利。",instr:"翻译",instrEn:"Translate",body:"In short, the trip went smoothly."},{q:"选择：“in short”用（总之 / 至于）。",a:"总之",instr:"选择",instrEn:"Choose",body:"“in short”用（总之 / 至于）。"}],note:"放在总结性结论前。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Placed before a summarizing conclusion.",typeEn:"Conjunction"},{id:"5.34.2",name:"趋向补语“V过”表示经过/越过",pinyin:"V guò",type:"趋向补语",explainEn:"Use V过 to show movement past/over something.",structure:"V + 过 + 地点/物体",examples:[{zh:"他跑过马路。",en:"He ran across the road."},{zh:"我每天都要走过这座桥。",en:"I walk across this bridge every day."},{zh:"汽车从我身边开过。",en:"The car drove past me."}],exercises:[{q:"填空：他跑___马路。",a:"过",instr:"填空",instrEn:"Fill in the blank",body:"他跑___马路。"},{q:"翻译：The car drove past me.",a:"汽车从我身边开过。",instr:"翻译",instrEn:"Translate",body:"The car drove past me."},{q:"选择：“walk across the bridge”用（走过 / 走起）桥。",a:"走过",instr:"选择",instrEn:"Choose",body:"“walk across the bridge”用（走过 / 走起）桥。"}],note:"这里的“过”是方向/路径，不是经历助词“过”。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Here 过 is direction/path, not the experiential particle 过.",typeEn:"Directional compl."},{id:"5.34.3",name:"趋向补语“V开”表示分开/打开/离开",pinyin:"V kāi",type:"结果/趋向补语",explainEn:"Use V开 to show things separate, open, spread out, or move away.",structure:"V + 开",examples:[{zh:"请把门打开。",en:"Please open the door."},{zh:"大家让开一点儿。",en:"Everyone, move aside a little."},{zh:"消息很快传开了。",en:"The news spread quickly."}],exercises:[{q:"填空：请把门打___。",a:"开",instr:"填空",instrEn:"Fill in the blank",body:"请把门打___。"},{q:"翻译：The news spread quickly.",a:"消息很快传开了。",instr:"翻译",instrEn:"Translate",body:"The news spread quickly."},{q:"选择：“move aside”用（让开 / 让过）。",a:"让开",instr:"选择",instrEn:"Choose",body:"“move aside”用（让开 / 让过）。"}],note:"常见：打开、分开、离开、传开、让开。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Common: 打开, 分开, 离开, 传开, 让开.",typeEn:"Result / Directional"}]},{num:35,title:"植物会出汗",points:[{id:"5.35.1",name:"副词“赶快”",pinyin:"gǎnkuài",type:"副词",explainEn:"Use 赶快 to mean “hurry up / quickly because time is pressing”.",structure:"赶快 + V",examples:[{zh:"快下雨了，赶快回家吧。",en:"It's going to rain; hurry home."},{zh:"你赶快去医院看看。",en:"Go to the hospital quickly."},{zh:"时间不多了，我们赶快开始。",en:"There isn't much time; let's start quickly."}],exercises:[{q:"填空：要迟到了，___走。",a:"赶快",instr:"填空",instrEn:"Fill in the blank",body:"要迟到了，___走。"},{q:"翻译：Hurry home.",a:"赶快回家。",instr:"翻译",instrEn:"Translate",body:"Hurry home."},{q:"选择：有紧迫感的“quickly”用（赶快 / 逐步）。",a:"赶快",instr:"选择",instrEn:"Choose",body:"有紧迫感的“quickly”用（赶快 / 逐步）。"}],note:"比“快”更强调抓紧时间。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"More than 快, it stresses hurrying.",typeEn:"Adverb"},{id:"5.35.2",name:"量词/名词“片”",pinyin:"piàn",type:"量词",explainEn:"Use 片 for flat pieces, areas, or waves/groups of things.",structure:"一片 + 面包/叶子/云/掌声",examples:[{zh:"桌上有一片面包。",en:"There is a slice of bread on the table."},{zh:"天空中有一片云。",en:"There is a patch of cloud in the sky."},{zh:"演出结束后响起一片掌声。",en:"A wave of applause arose after the show."}],exercises:[{q:"填空：一___面包",a:"片",instr:"填空",instrEn:"Fill in the blank",body:"一___面包"},{q:"翻译：a wave of applause",a:"一片掌声",instr:"翻译",instrEn:"Translate",body:"a wave of applause"},{q:"选择：面包片的量词是（片 / 根）。",a:"片",instr:"选择",instrEn:"Choose",body:"面包片的量词是（片 / 根）。"}],note:"可表示“一片叶子/面包/海/掌声”等。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Can count 一片叶子/面包/海/掌声, etc.",typeEn:"Measure word"},{id:"5.35.3",name:"“根本”表示从根本上/完全（常与否定）",pinyin:"gēnběn",type:"名词/副词",explainEn:"Use 根本 with negatives for “not at all”; it can also mean “fundamental/root”.",structure:"根本 + 不/没；根本问题",examples:[{zh:"我根本不知道这件事。",en:"I do not know about this at all."},{zh:"这个办法根本行不通。",en:"This method simply will not work."},{zh:"我们要解决根本问题。",en:"We need to solve the fundamental problem."}],exercises:[{q:"填空：我___没听说过。",a:"根本",instr:"填空",instrEn:"Fill in the blank",body:"我___没听说过。"},{q:"翻译：This method will not work at all.",a:"这个办法根本行不通。",instr:"翻译",instrEn:"Translate",body:"This method will not work at all."},{q:"选择：“fundamental problem”可说（根本问题 / 根本地问题）。",a:"根本问题",instr:"选择",instrEn:"Choose",body:"“fundamental problem”可说（根本问题 / 根本地问题）。"}],note:"副词时常和“不、没”一起使用。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"As an adverb it's used with 不/没.",typeEn:"Noun / Adverb"}]},{num:36,title:"老舍与养花",points:[{id:"5.36.1",name:"“除非……才…… / 除非……否则……”",pinyin:"chúfēi ... cái / fǒuzé ...",type:"条件复句",explainEn:"Use 除非 for an essential condition: “unless / only if”.",structure:"除非 + 条件，才 + 结果；除非 + 条件，否则 + 后果",examples:[{zh:"除非你去，我才去。",en:"I will go only if you go."},{zh:"除非下大雨，否则比赛照常进行。",en:"Unless it rains heavily, the game will continue as usual."},{zh:"除非努力，否则很难成功。",en:"Unless you work hard, it is hard to succeed."}],exercises:[{q:"填空：___你去，我___去。",a:"除非；才",instr:"填空",instrEn:"Fill in the blank",body:"___你去，我___去。"},{q:"翻译：Unless it rains, the game continues.",a:"除非下雨，否则比赛继续。",instr:"翻译",instrEn:"Translate",body:"Unless it rains, the game continues."},{q:"连接：认真准备。不然很难通过。",a:"除非认真准备，否则很难通过。",instr:"连接",instrEn:"Join the sentences",body:"认真准备。不然很难通过。"}],note:"“除非”提出唯一或必要条件。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"除非 introduces the only/necessary condition.",typeEn:"Conditional"},{id:"5.36.2",name:"副词“直”表示一直不停地做",pinyin:"zhí",type:"副词",explainEn:"Use 直 before a verb to mean “continuously / keep doing”, often in a strong emotional result.",structure:"直 + V；Adj/情绪 + 得 + 直 + V",examples:[{zh:"孩子疼得直哭。",en:"The child hurt so much that he kept crying."},{zh:"他听了直点头。",en:"He kept nodding after hearing it."},{zh:"冷风吹得我直发抖。",en:"The cold wind made me keep shivering."}],exercises:[{q:"填空：孩子疼得___哭。",a:"直",instr:"填空",instrEn:"Fill in the blank",body:"孩子疼得___哭。"},{q:"翻译：He kept nodding.",a:"他听了直点头。",instr:"翻译",instrEn:"Translate",body:"He kept nodding."},{q:"选择：“keep shivering”可说（直发抖 / 逐步发抖）。",a:"直发抖",instr:"选择",instrEn:"Choose",body:"“keep shivering”可说（直发抖 / 逐步发抖）。"}],note:"常见于“急得直哭、笑得直不起腰”等强烈状态。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Common in strong states like 急得直哭, 笑得直不起腰.",typeEn:"Adverb"},{id:"5.36.3",name:"副词“反正”",pinyin:"fǎnzhèng",type:"副词",explainEn:"Use 反正 to mean “anyway / in any case”; the result will not change.",structure:"反正 + 结论/决定",examples:[{zh:"反正明天不上班，我们晚点儿睡吧。",en:"Anyway, we don't work tomorrow, so let's sleep later."},{zh:"你去不去都行，反正我会去。",en:"Whether you go or not, I will go anyway."},{zh:"反正已经迟到了，着急也没用。",en:"We're already late anyway; worrying won't help."}],exercises:[{q:"填空：___我已经决定了。",a:"反正",instr:"填空",instrEn:"Fill in the blank",body:"___我已经决定了。"},{q:"翻译：I will go anyway.",a:"反正我会去。",instr:"翻译",instrEn:"Translate",body:"I will go anyway."},{q:"选择：“anyway”用（反正 / 至今）。",a:"反正",instr:"选择",instrEn:"Choose",body:"“anyway”用（反正 / 至今）。"}],note:"常表示无论前面情况怎样，后面的结论不变。",source:"https://courses.chinesezerotohero.com/p/hsk-5-course",noteEn:"Means the conclusion holds regardless of the situation.",typeEn:"Adverb"}]}],s={series:e,unit:5,lessons:n};export{s as default,n as lessons,e as series,t as unit};
